'',v_authorized->''postal_code'',\n      ''country'',v_authorized->''country'',''latitude'',v_authorized->''latitude'',\n      ''longitude'',v_authorized->''longitude'',\n      ''google_maps_url'',v_authorized->''google_maps_url'',\n      ''amenities'',v_authorized->''amenities'',''check_in_from'',v_authorized->''check_in_from'',\n      ''check_out_until'',v_authorized->''check_out_until'',\n      ''cover_image_url'',v_authorized->''cover_image_url'',''photos'',v_authorized->''photos'');\n  end if;\n  select jsonb_build_object(\n    ''title'',hotel.title,''title_i18n'',hotel.title_i18n,\n    ''description'',hotel.description,''description_i18n'',hotel.description_i18n,\n    ''city'',hotel.city,''address_line'',hotel.address_line,''district'',hotel.district,\n    ''postal_code'',hotel.postal_code,''country'',hotel.country,\n    ''latitude'',hotel.latitude,''longitude'',hotel.longitude,\n    ''google_maps_url'',hotel.google_maps_url,''amenities'',hotel.amenities,\n    ''check_in_from'',hotel.check_in_from,''check_out_until'',hotel.check_out_until,\n    ''cover_image_url'',hotel.cover_image_url,''photos'',hotel.photos)\n  into v_actual from public.hotels hotel\n  where hotel.id=''9b6d99a0-923a-4fbc-be54-c066e856e6ca''::uuid;\n  return v_actual is not null and v_actual is not distinct from v_expected;\nexception when no_data_found or too_many_rows then\n  return false;\nend;\n","result_type":"boolean","security_definer":true,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION public.hotel_v2_admin_c_seven_kamares_allocation_contract_is_exact()\n RETURNS boolean\n LANGUAGE sql\n STABLE\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\n  with expected_rules(code,allocation_mode,min_guest_count,max_guest_count) as (\n    values\n      (''guests-1-4-choice'',''customer_choice'',1,4),\n      (''guests-5-bundle'',''required_bundle'',5,5),\n      (''guests-6-bundle'',''required_bundle'',6,6),\n      (''guests-7-bundle'',''required_bundle'',7,7),\n      (''guests-8-bundle'',''required_bundle'',8,8)\n  ), expected_items(rule_code,room_type_id,physical,pricing) as (\n    values\n      (''guests-1-4-choice'',''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,null::smallint,null::smallint),\n      (''guests-1-4-choice'',''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid,null::smallint,null::smallint),\n      (''guests-5-bundle'',''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,3::smallint,2::smallint),\n      (''guests-5-bundle'',''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid,2::smallint,2::smallint),\n      (''guests-6-bundle'',''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,3::smallint,3::smallint),\n      (''guests-6-bundle'',''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid,3::smallint,3::smallint),\n      (''guests-7-bundle'',''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,4::smallint,4::smallint),\n      (''guests-7-bundle'',''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid,3::smallint,4::smallint),\n      (''guests-8-bundle'',''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,4::smallint,4::smallint),\n      (''guests-8-bundle'',''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid,4::smallint,4::smallint)\n  ), actual_rules as (\n    select rule.code,rule.allocation_mode,rule.min_guest_count,\n      rule.max_guest_count,rule.is_active,rule.review_status\n    from public.hotel_room_allocation_rules rule\n    where rule.hotel_id=''9b6d99a0-923a-4fbc-be54-c066e856e6ca''::uuid\n  ), actual_items as (\n    select rule.code rule_code,item.hotel_id,item.room_type_id,\n      item.allocated_guest_count physical,item.pricing_guest_count pricing,\n      item.units_required,item.allocated_guest_counts,\n      item.pricing_guest_counts\n    from public.hotel_room_allocation_rule_items item\n    join public.hotel_room_allocation_rules rule on rule.id=item.allocation_rule_id\n    where rule.hotel_id=''9b6d99a0-923a-4fbc-be54-c066e856e6ca''::uuid\n  )\n  select (select count(*) from actual_rules)=5\n    and not exists(\n      select 1 from expected_rules expected full join actual_rules actual using(code)\n      where expected.code is null or actual.code is null\n        or actual.allocation_mode is distinct from expected.allocation_mode\n        or actual.min_guest_count is distinct from expected.min_guest_count\n        or actual.max_guest_count is distinct from expected.max_guest_count\n        or actual.is_active is distinct from true\n        or actual.review_status is distinct from ''reviewed'')\n    and (select count(*) from actual_items)=10\n    and not exists(\n      select 1 from expected_items expected full join actual_items actual\n        using(rule_code,room_type_id)\n      where expected.rule_code is null or actual.rule_code is null\n        or expected.room_type_id is null or actual.room_type_id is null\n        or actual.hotel_id is distinct from\n          ''9b6d99a0-923a-4fbc-be54-c066e856e6ca''::uuid\n        or actual.physical is distinct from expected.physical\n        or actual.pricing is distinct from expected.pricing\n        or actual.units_required is distinct from 1\n        or actual.allocated_guest_counts is not null\n        or actual.pricing_guest_counts is not null)\n$function$\n","identity":"hotel_v2_admin_c_seven_kamares_allocation_contract_is_exact()","owner":"postgres","prosrc":"\n  with expected_rules(code,allocation_mode,min_guest_count,max_guest_count) as (\n    values\n      (''guests-1-4-choice'',''customer_choice'',1,4),\n      (''guests-5-bundle'',''required_bundle'',5,5),\n      (''guests-6-bundle'',''required_bundle'',6,6),\n      (''guests-7-bundle'',''required_bundle'',7,7),\n      (''guests-8-bundle'',''required_bundle'',8,8)\n  ), expected_items(rule_code,room_type_id,physical,pricing) as (\n    values\n      (''guests-1-4-choice'',''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,null::smallint,null::smallint),\n      (''guests-1-4-choice'',''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid,null::smallint,null::smallint),\n      (''guests-5-bundle'',''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,3::smallint,2::smallint),\n      (''guests-5-bundle'',''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid,2::smallint,2::smallint),\n      (''guests-6-bundle'',''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,3::smallint,3::smallint),\n      (''guests-6-bundle'',''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid,3::smallint,3::smallint),\n      (''guests-7-bundle'',''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,4::smallint,4::smallint),\n      (''guests-7-bundle'',''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid,3::smallint,4::smallint),\n      (''guests-8-bundle'',''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,4::smallint,4::smallint),\n      (''guests-8-bundle'',''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid,4::smallint,4::smallint)\n  ), actual_rules as (\n    select rule.code,rule.allocation_mode,rule.min_guest_count,\n      rule.max_guest_count,rule.is_active,rule.review_status\n    from public.hotel_room_allocation_rules rule\n    where rule.hotel_id=''9b6d99a0-923a-4fbc-be54-c066e856e6ca''::uuid\n  ), actual_items as (\n    select rule.code rule_code,item.hotel_id,item.room_type_id,\n      item.allocated_guest_count physical,item.pricing_guest_count pricing,\n      item.units_required,item.allocated_guest_counts,\n      item.pricing_guest_counts\n    from public.hotel_room_allocation_rule_items item\n    join public.hotel_room_allocation_rules rule on rule.id=item.allocation_rule_id\n    where rule.hotel_id=''9b6d99a0-923a-4fbc-be54-c066e856e6ca''::uuid\n  )\n  select (select count(*) from actual_rules)=5\n    and not exists(\n      select 1 from expected_rules expected full join actual_rules actual using(code)\n      where expected.code is null or actual.code is null\n        or actual.allocation_mode is distinct from expected.allocation_mode\n        or actual.min_guest_count is distinct from expected.min_guest_count\n        or actual.max_guest_count is distinct from expected.max_guest_count\n        or actual.is_active is distinct from true\n        or actual.review_status is distinct from ''reviewed'')\n    and (select count(*) from actual_items)=10\n    and not exists(\n      select 1 from expected_items expected full join actual_items actual\n        using(rule_code,room_type_id)\n      where expected.rule_code is null or actual.rule_code is null\n        or expected.room_type_id is null or actual.room_type_id is null\n        or actual.hotel_id is distinct from\n          ''9b6d99a0-923a-4fbc-be54-c066e856e6ca''::uuid\n        or actual.physical is distinct from expected.physical\n        or actual.pricing is distinct from expected.pricing\n        or actual.units_required is distinct from 1\n        or actual.allocated_guest_counts is not null\n        or actual.pricing_guest_counts is not null)\n","result_type":"boolean","security_definer":false,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION public.hotel_v2_external_calendar_activation_function_fingerprints()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nselect jsonb_object_agg(signature,public.hotel_v2_external_calendar_worker_hash(\n  to_jsonb(hotels_lifecycle_private.predecessor_definition(to_regprocedure(signature)))) order by signature)\nfrom (values\n  (''public.hotel_v2_h3_2a_require_partner_hotel_access(uuid,uuid,text,boolean)''),\n  (''public.hotel_v2_partner_list_assigned_properties(uuid)''),\n  (''public.hotel_v2_admin_apply_partner_hotel_permissions(jsonb,uuid,uuid)''),\n  (''public.hotel_v2_admin_create_property_draft(uuid,jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_guest_policy_plan(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_room_control_plan(jsonb,uuid)''),\n  (''public.hotel_v2_admin_get_content_control(uuid)''),\n  (''public.hotel_v2_admin_apply_operational_assignment_plan(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_property_control_plan(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_pricing_control_plan(jsonb,uuid,text)''),\n  (''public.hotel_v2_admin_apply_h3_1_configuration_h3_1p_core(jsonb,uuid)''),\n  (''public.hotel_v2_h3_2b_flags_off()''),\n  (''public.hotel_v2_partner_get_workspace(uuid,uuid,date,date)''),\n  (''public.hotel_v2_admin_create_property_draft_admin_b_core(uuid,jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_guest_policy_plan_admin_b_core(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_workspace_plan_admin_b_core(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_calendar_plan_admin_c_core(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_workspace_plan_admin_c_core(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_h3_1_configuration_admin_c_core(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_legacy_pricing_promotion_admin_c_core(jsonb,uuid)'')\n) expected(signature)\n$function$\n","identity":"hotel_v2_external_calendar_activation_function_fingerprints()","owner":"postgres","prosrc":"\nselect jsonb_object_agg(signature,public.hotel_v2_external_calendar_worker_hash(\n  to_jsonb(hotels_lifecycle_private.predecessor_definition(to_regprocedure(signature)))) order by signature)\nfrom (values\n  (''public.hotel_v2_h3_2a_require_partner_hotel_access(uuid,uuid,text,boolean)''),\n  (''public.hotel_v2_partner_list_assigned_properties(uuid)''),\n  (''public.hotel_v2_admin_apply_partner_hotel_permissions(jsonb,uuid,uuid)''),\n  (''public.hotel_v2_admin_create_property_draft(uuid,jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_guest_policy_plan(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_room_control_plan(jsonb,uuid)''),\n  (''public.hotel_v2_admin_get_content_control(uuid)''),\n  (''public.hotel_v2_admin_apply_operational_assignment_plan(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_property_control_plan(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_pricing_control_plan(jsonb,uuid,text)''),\n  (''public.hotel_v2_admin_apply_h3_1_configuration_h3_1p_core(jsonb,uuid)''),\n  (''public.hotel_v2_h3_2b_flags_off()''),\n  (''public.hotel_v2_partner_get_workspace(uuid,uuid,date,date)''),\n  (''public.hotel_v2_admin_create_property_draft_admin_b_core(uuid,jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_guest_policy_plan_admin_b_core(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_workspace_plan_admin_b_core(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_calendar_plan_admin_c_core(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_workspace_plan_admin_c_core(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_h3_1_configuration_admin_c_core(jsonb,uuid)''),\n  (''public.hotel_v2_admin_apply_legacy_pricing_promotion_admin_c_core(jsonb,uuid)'')\n) expected(signature)\n","result_type":"jsonb","security_definer":true,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION public.hotel_v2_external_calendar_provider_lineage_bridge_is_exact()\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\ndeclare\n  v_receipt hotels_v2_private.hotel_external_calendar_provider_evolution_receipts%rowtype;\n  v_live_definitions jsonb;\n  v_live_sources jsonb;\n  v_pricing_scoped_lineage jsonb;\n  v_pricing_scoped_lineage_source_hash text;\n  v_transaction_preservation_source_hash text;\n  v_inflight boolean:=false;\n  v_finalized boolean:=false;\n  v_safe_function oid;\nbegin\n  if (select count(*)\n      from hotels_v2_private.hotel_external_calendar_provider_evolution_receipts)<>1 then\n    return false;\n  end if;\n  select * into strict v_receipt\n  from hotels_v2_private.hotel_external_calendar_provider_evolution_receipts\n  where id=1;\n  v_pricing_scoped_lineage:=\n    public.hotel_v2_seven_arches_pricing_scoped_lineage();\n  select encode(extensions.digest(convert_to(hotels_lifecycle_private.predecessor_source(procedure_row.oid),''UTF8''),\n    ''sha256''),''hex'') into v_pricing_scoped_lineage_source_hash\n  from pg_proc procedure_row where procedure_row.oid=\n    ''public.hotel_v2_seven_arches_pricing_scoped_lineage()''::regprocedure;\n  select encode(extensions.digest(convert_to(hotels_lifecycle_private.predecessor_source(procedure_row.oid),''UTF8''),\n    ''sha256''),''hex'') into v_transaction_preservation_source_hash\n  from pg_proc procedure_row where procedure_row.oid=\n    ''public.hotel_v2_7a_pricing_activation_transaction_is_preserved()''::regprocedure;\n  v_inflight:=v_receipt.receipt_hash is null\n    and v_receipt.safe_function_source_hash is null\n    and v_receipt.evolved_protected_fingerprints is null\n    and v_receipt.evolved_protected_fingerprint is null\n    and v_receipt.evolution_helper_fingerprints is null\n    and v_receipt.fingerprint_helper_source_hashes is null\n    and to_regprocedure(\n      ''hotels_v2_private.hotel_external_calendar_evolve_function(text,text,text,integer)'')\n      is not null\n    and not exists(select 1 from pg_trigger trigger_row\n      where trigger_row.tgrelid=\n        ''hotels_v2_private.hotel_external_calendar_provider_evolution_receipts''::regclass\n        and not trigger_row.tgisinternal\n        and trigger_row.tgname=\n          ''hotel_external_calendar_provider_evolution_receipt_immutable'')\n    and not (select attribute.attnotnull from pg_attribute attribute\n      where attribute.attrelid=\n        ''hotels_v2_private.hotel_external_calendar_provider_evolution_receipts''::regclass\n        and attribute.attname=''receipt_hash'' and not attribute.attisdropped);\n  if not v_inflight then\n    v_safe_function:=to_regprocedure(\n      ''public.hotel_v2_external_calendar_provider_evolution_is_safe()'');\n    if v_safe_function is null then\n      return false;\n    end if;\n    v_finalized:=v_receipt.evolved_protected_fingerprints is not null\n      and v_receipt.evolved_protected_fingerprint=\n        public.hotel_v2_external_calendar_worker_hash(\n          v_receipt.evolved_protected_fingerprints)\n      and v_receipt.evolution_helper_fingerprints is not null\n      and v_receipt.fingerprint_helper_source_hashes is not null\n      and v_receipt.safe_function_source_hash=\n        public.hotel_v2_external_calendar_worker_hash(\n          to_jsonb(hotels_lifecycle_private.predecessor_definition(v_safe_function)))\n      and v_receipt.receipt_hash=\n        public.hotel_v2_external_calendar_worker_hash(jsonb_set(\n          to_jsonb(v_receipt)-''receipt_hash'',''{created_at}'',to_jsonb(\n            (extract(epoch from v_receipt.created_at)*1000000)::bigint),false))\n      and not exists(select 1 from unnest(array[\n          ''evolved_protected_fingerprints'',''evolved_protected_fingerprint'',\n          ''evolved_function_fingerprints'',''evolved_function_source_hashes'',\n          ''evolved_reviewed_pricing_catalog_fingerprint'',\n          ''evolution_helper_fingerprints'',''fingerprint_helper_source_hashes'',\n          ''safe_function_source_hash'',''receipt_hash'']::text[]) expected(column_name)\n        left join pg_attribute attribute on attribute.attrelid=\n          ''hotels_v2_private.hotel_external_calendar_provider_evolution_receipts''::regclass\n          and attribute.attname=expected.column_name and not attribute.attisdropped\n        where attribute.attnum is null or not attribute.attnotnull)\n      and exists(select 1 from pg_trigger trigger_row\n        where trigger_row.tgrelid=\n          ''hotels_v2_private.hotel_external_calendar_provider_evolution_receipts''::regclass\n          and not trigger_row.tgisinternal\n          and trigger_row.tgname=\n            ''hotel_external_calendar_provider_evolution_receipt_immutable''\n          and trigger_row.tgenabled=''O''\n          and trigger_row.tgfoid=\n            ''public.hotel_v2_h3_2a_reject_immutable_change()''::regprocedure);\n  end if;\n  if v_receipt.evolved_function_