tivity.correlation_id\n        and receipt.idempotency_key=v_correlation.idempotency_key\n        and receipt.request_hash=v_correlation.request_hash\n        and receipt.result->>''contract_version''=''hotels_v2_external_calendar_apply_result_v1''\n        and receipt.result->>''hotel_id''=v_review.hotel_id::text\n        and receipt.result->>''partner_id''=v_review.partner_id::text\n        and receipt.result->>''correlation_id''=v_activity.correlation_id::text\n        and receipt.result->>''idempotency_key''=v_correlation.idempotency_key::text\n        and receipt.result->>''request_hash''=v_correlation.request_hash\n        and receipt.result->''changed''=''true''::jsonb\n        and receipt.result->''replayed''=''false''::jsonb\n        and receipt.result?&array[''contract_version'',''hotel_id'',''partner_id'',''correlation_id'',\n          ''idempotency_key'',''replayed'',''changed'',''activity'',''request_hash'']\n        and public.hotel_v2_h2a_keys_allowed(receipt.result,array[''contract_version'',''hotel_id'',\n          ''partner_id'',''correlation_id'',''idempotency_key'',''replayed'',''changed'',''activity'',''request_hash''])\n        and receipt.result->''activity''=jsonb_build_array(v_activity_projection);\n      if v_count<>1 or exists(select 1\n          from hotels_v2_private.hotel_external_calendar_admin_receipts receipt\n          where receipt.correlation_id=v_activity.correlation_id) then return false; end if;\n    else return false;\n    end if;\n  end loop;\n\n  -- No consumed review, correlation, or excluded receipt may be orphaned from\n  -- the exact external activity chain checked above.\n  if exists(select 1\n      from hotels_v2_private.hotel_external_calendar_plan_reviews review\n      where review.consumed_at is not null\n        and not exists(select 1 from public.hotel_activity_log activity\n          where activity.source=''hotels_v2_external_calendar_control''\n            and activity.correlation_id=review.consumed_correlation_id)\n        and (select count(*)\n          from hotels_v2_private.hotel_external_calendar_partner_proposals proposal\n          join public.hotel_partner_action_receipts receipt\n            on receipt.action=''h3_2d_external_calendar_provider_proposal''\n           and receipt.partner_id=proposal.partner_id\n           and receipt.hotel_id=proposal.hotel_id\n           and receipt.actor_user_id=proposal.actor_id\n           and receipt.correlation_id=proposal.submission_correlation_id\n           and receipt.idempotency_key=proposal.submission_idempotency_key\n           and receipt.request_hash=proposal.submission_request_hash\n           and receipt.result=jsonb_build_object(\n             ''contract_version'',''hotels_v2_external_calendar_partner_proposal_receipt_v1'',\n             ''proposal_id'',proposal.id,''hotel_id'',proposal.hotel_id,\n             ''partner_id'',proposal.partner_id,\n             ''correlation_id'',proposal.submission_correlation_id,\n             ''idempotency_key'',proposal.submission_idempotency_key,\n             ''request_hash'',proposal.submission_request_hash,\n             ''status'',''pending_admin_review'')\n          where proposal.partner_review_id=review.id\n            and proposal.actor_id=review.actor_id\n            and proposal.partner_id=review.partner_id\n            and proposal.assignment_id=review.assignment_id\n            and proposal.hotel_id=review.hotel_id\n            and proposal.permission_version=review.permission_version\n            and proposal.access_snapshot_token=review.access_snapshot_token\n            and proposal.snapshot_token=review.snapshot_token\n            and proposal.reviewed_plan=review.reviewed_plan\n            and proposal.plan_fingerprint=review.plan_fingerprint\n            and proposal.submission_correlation_id=review.consumed_correlation_id\n            and proposal.submitted_at=review.consumed_at)<>1)\n     or exists(select 1\n      from hotels_v2_private.hotel_external_calendar_correlations correlation\n      where not exists(select 1 from public.hotel_activity_log activity\n        where activity.source=''hotels_v2_external_calendar_control''\n          and activity.correlation_id=correlation.correlation_id))\n     or exists(select 1\n      from hotels_v2_private.hotel_external_calendar_admin_receipts receipt\n      where not exists(select 1 from public.hotel_activity_log activity\n        where activity.source=''hotels_v2_external_calendar_control''\n          and activity.correlation_id=receipt.correlation_id))\n     or exists(select 1 from public.hotel_partner_action_receipts receipt\n      where receipt.action=''h3_2d_external_calendar'' and not exists(select 1\n        from public.hotel_activity_log activity\n        where activity.source=''hotels_v2_external_calendar_control''\n          and activity.correlation_id=receipt.correlation_id))\n     or exists(select 1\n      from hotels_v2_private.hotel_external_calendar_partner_proposals proposal\n      where (select count(*)\n        from hotels_v2_private.hotel_external_calendar_plan_reviews review\n        join public.hotel_partner_action_receipts receipt\n          on receipt.action=''h3_2d_external_calendar_provider_proposal''\n         and receipt.partner_id=proposal.partner_id\n         and receipt.hotel_id=proposal.hotel_id\n         and receipt.actor_user_id=proposal.actor_id\n         and receipt.correlation_id=proposal.submission_correlation_id\n         and receipt.idempotency_key=proposal.submission_idempotency_key\n         and receipt.request_hash=proposal.submission_request_hash\n         and receipt.result=jsonb_build_object(\n           ''contract_version'',''hotels_v2_external_calendar_partner_proposal_receipt_v1'',\n           ''proposal_id'',proposal.id,''hotel_id'',proposal.hotel_id,\n           ''partner_id'',proposal.partner_id,\n           ''correlation_id'',proposal.submission_correlation_id,\n           ''idempotency_key'',proposal.submission_idempotency_key,\n           ''request_hash'',proposal.submission_request_hash,\n           ''status'',''pending_admin_review'')\n        where review.id=proposal.partner_review_id\n          and review.actor_type=''partner''\n          and review.actor_id=proposal.actor_id\n          and review.partner_id=proposal.partner_id\n          and review.assignment_id=proposal.assignment_id\n          and review.hotel_id=proposal.hotel_id\n          and review.permission_version=proposal.permission_version\n          and review.access_snapshot_token=proposal.access_snapshot_token\n          and review.snapshot_token=proposal.snapshot_token\n          and review.reviewed_plan=proposal.reviewed_plan\n          and review.plan_fingerprint=proposal.plan_fingerprint\n          and review.consumed_correlation_id=proposal.submission_correlation_id\n          and review.consumed_at=proposal.submitted_at)<>1)\n     or exists(select 1 from public.hotel_partner_action_receipts receipt\n      where receipt.action=''h3_2d_external_calendar_provider_proposal''\n        and (select count(*)\n          from hotels_v2_private.hotel_external_calendar_partner_proposals proposal\n          join hotels_v2_private.hotel_external_calendar_plan_reviews review\n            on review.id=proposal.partner_review_id\n           and review.actor_type=''partner''\n           and review.actor_id=proposal.actor_id\n           and review.partner_id=proposal.partner_id\n           and review.assignment_id=proposal.assignment_id\n           and review.hotel_id=proposal.hotel_id\n           and review.permission_version=proposal.permission_version\n           and review.access_snapshot_token=proposal.access_snapshot_token\n           and review.snapshot_token=proposal.snapshot_token\n           and review.reviewed_plan=proposal.reviewed_plan\n           and review.plan_fingerprint=proposal.plan_fingerprint\n           and review.consumed_correlation_id=proposal.submission_correlation_id\n           and review.consumed_at=proposal.submitted_at\n          where receipt.partner_id=proposal.partner_id\n            and receipt.hotel_id=proposal.hotel_id\n            and receipt.actor_user_id=proposal.actor_id\n            and receipt.correlation_id=proposal.submission_correlation_id\n            and receipt.idempotency_key=proposal.submission_idempotency_key\n            and receipt.request_hash=proposal.submission_request_hash\n            and receipt.result=jsonb_build_object(\n              ''contract_version'',''hotels_v2_external_calendar_partner_proposal_receipt_v1'',\n              ''proposal_id'',proposal.id,''hotel_id'',proposal.hotel_id,\n              ''partner_id'',proposal.partner_id,\n              ''correlation_id'',proposal.submission_correlation_id,\n              ''idempotency_key'',proposal.submission_idempotency_key,\n              ''request_hash'',proposal.submission_request_hash,\n              ''status'',''pending_admin_review''))<>1) then\n    return false;\n  end if;\n\n  if to_regclass(''hotels_v2_private.hotel_external_calendar_provider_evolution_receipts'') is null then\n    return true;\n  end if;\n  execute ''select count(*) from hotels_v2_private.hotel_external_calendar_provider_evolution_receipts''\n    into v_provider_receipt_count;\n  if v_provider_receipt_count=0 then return true; end if;\n  if v_provider_receipt_count<>1 then return false; end if;\n  execute ''select provider_source_baseline,manual_source_fingerprint from hotels_v2_private.hotel_external_calendar_provider_evolution_receipts where id=1''\n    into v_baseline,v_manual_fingerprint;\n  if v_baseline is null or jsonb_typeof(v_baseline)<>''array''\n     or v_manual_fingerprint is null\n     or v_manual_fingerprint<>public.hotel_v2_external_calendar_worker_hash(coalesce(\n       (select jsonb_agg(to_jsonb(source) order by source.id)\n        from public.hotel_calendar_source_configs source where source.source_type=''manual''),''[]''::jsonb))\n     or exists(select 1 from public.hotel_calendar_source_configs source\n       where source.source_type<>''manual''\n         and source.source_type not in(''booking_com'',''airbnb'',''ical''))\n     or exists(select 1 from jsonb_array_elements(v_baseline) baseline(value)\n       where jsonb_typeof(baseline.value)<>''object''\n         or baseline.value->>''source_type'' not in(''booking_com'',''airbnb'',''ical''))\n     or exists(select 1 from jsonb_array_elements(v_baseline) baseline(value)\n       where not exists(select 1 from public.hotel_calendar_source_configs source\n         where source.id=(baseline.value->>''id'')::uuid)) then\n    return false;\n  end if;\n\n  -- A current supported source is either byte-identical to the immutable\n  -- provider baseline or its exact source-config projection is the result of a\n  -- reviewed calendar_source operation. Secret/sync operations never qualify.\n  if exists(select 1 from public.hotel_calendar_source_configs source\n      where source.source_type in(''booking_com'',''airbnb'',''ical'')\n        and not exists(select 1 from jsonb_array_elements(v_baseline) baseline(value)\n          where baseline.value=to_jsonb(source))\n        and not exists(select 1 from public.hotel_activity_log activity\n          join hotels_v2_private.hotel_external_calendar_plan_reviews review\n            on review.consumed_correlation_id=activity.correlation_id\n           and review.consumed_at is not null\n          cross join lateral (select review.reviewed_plan#>''{operations,0}'' operation) reviewed\n          where activity.source=''hotels_v2_external_calendar_control''\n            and activity.entity_type=''calendar_source'' and activity.entity_id=source.id\n            and activity.hotel_id=source.hotel_id\n            and reviewed.operation->>''entity''=''calendar_source''\n            and reviewed.operation->>''action'' in(''create'',''update'',''enable'',''disable'')\n            and coalesce(reviewed.operation#>>''{payload,room_type_id}'',\n              reviewed.operation#>>''{expected_original,room_type_id}'')=source.room_type_id::text\n            and coalesce(reviewed.operation#>>''{payload,source_type}'',\n              reviewed.operation#>>''{expected_original,source_type}'',\n              case when source.source_type=''ical'' then ''ical'' end)=source.source_type\n            and (activity.after_state-array[''health'',''secret_configured'',''binding_version'']::text[])=\n              jsonb_build_object(''id'',source.id,''hotel_id'',source.hotel_id,\n                ''room_type_id'',source.room_type_id,''code'',source.code,''source_type'',source.source_type,\n                ''is_enabled'',source.is_enabled,''review_status'',source.review_status,\n                ''priority'',source.priority,''version'',source.version,''updated_at'',source.updated_at,\n                ''sync_interval_minutes'',(source.configuration->>''sync_interval_minutes'')::integer,\n                ''units_per_event'',(source.configuration->>''units_per_event'')::integer))) then\n    return false;\n  end if;\n  return true;\nexception when invalid_text_representation or no_data_found or too_many_rows then\n  return false;\nend\n","result_type":"boolean","security_definer":true,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION public.hotel_v2_external_calendar_site_settings_fingerprint()\n RETURNS text\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\ndeclare\n  v_setting public.site_settings%rowtype;\n  v_receipt hotels_v2_private.hotel_external_calendar_activation_receipts%rowtype;\nbegin\n  if to_regprocedure(''public.hotel_v2_external_calendar_worker_hash(jsonb)'') is null\n     or to_regprocedure(\n       ''public.hotel_v2_external_calendar_activation_function_fingerprints()'') is null\n     or to_regprocedure(\n       ''public.hotel_v2_partner_workspace_function_lineage_is_exact()'') is null\n     or to_regprocedure(''public.hotel_v2_h3_2a_reject_immutable_change()'') is null\n     or (select count(*) from public.site_settings)<>1\n     or not exists(select 1 from public.site_settings where id=1)\n     or (select count(*)\n       from hotels_v2_private.hotel_external_calendar_activation_receipts)<>1\n     or not exists(select 1\n       from hotels_v2_private.hotel_external_calendar_activation_receipts where id=1) then\n    return null;\n  end if;\n\n  select * into strict v_setting from public.site_settings where id=1;\n  select * into strict v_receipt\n  from hotels_v2_private.hotel_external_calendar_activation_receipts where id=1;\n\n  -- OFF and ON are the two supported external-calendar states. The other\n  -- Hotels flags stay on the legacy production boundary in both states.\n  if v_setting.id is distinct from 1\n     or not hotels_lifecycle_private.predecessor_flag_exact(''hotel_rooms_v2_enabled'',v_setting.hotel_rooms_v2_enabled)\n     or (v_setting.hotel_external_sync_enabled is distinct from false\n       and v_setting.hotel_external_sync_enabled is distinct from true)\n     or v_setting.hotel_instant_booking_enabled is distinct from false\n     or not hotels_lifecycle_private.predecessor_flag_exact(''hotel_stripe_connect_enabled'',v_setting.hotel_stripe_connect_enabled) then\n    return null;\n  end if;\n\n  -- The 114350 row has no self-hash column, so historical integrity is its\n  -- exact constrained envelope plus its immutable/private security topology.\n  if v_receipt.id is distinct from 1\n     or (v_receipt.site_settings_without_external_fingerprint\n       ~''^[0-9a-f]{64}$'') is distinct from true\n     or jsonb_typeof(v_receipt.compatibility_function_fingerprints)\n       is distinct from ''object''\n     or v_receipt.created_at is null\n     or isfinite(v_receipt.created_at) is distinct from true then\n    return null;\n  end if;\n  -- Keep malformed non-object JSON away from the set-returning object\n  -- iterators above all other receipt checks.\n  if (select count(*) from jsonb_object_keys(\n       v_receipt.compatibility_function_fingerprints))<>20\n     or (v_receipt.compatibility_function_fingerprints ?& array[\n       ''public.hotel_v2_h3_2a_require_partner_hotel_access(uuid,uuid,text,boolean)'',\n       ''public.hotel_v2_partner_list_assigned_properties(uuid)'',\n       ''public.hotel_v2_admin_apply_partner_hotel_permissions(jsonb,uuid,uuid)'',\n       ''public.hotel_v2_admin_create_property_draft(uuid,jsonb,uuid)'',\n       ''public.hotel_v2_admin_apply_guest_policy_plan(jsonb,uuid)'',\n       ''public.hotel_v2_admin_apply_room_control_plan(jsonb,uuid)'',\n       ''public.hotel_v2_admin_get_content_control(uuid)'',\n       ''public.hotel_v2_admin_apply_operational_assignment_plan(jsonb,uuid)'',\n       ''public.hotel_v2_admin_apply_property_control_plan(jsonb,uuid)'',\n       ''public.hotel_v2_admin_apply_pricing_control_plan(jsonb,uuid,text)'',\n       ''public.hotel_v2_admin_apply_h3_1_configuration_h3_1p_core(jsonb,uuid)'',\n       ''public.hotel_v2_h3_2b_flags_off()'',\n       ''public.hotel_v2_partner_get_workspace(uuid,uuid,date,date)'',\n       ''public.hotel_v2_admin_create_property_draft_admin_b_core(uuid,jsonb,uuid)'',\n       ''public.hotel_v2_admin_apply_guest_policy_plan_admin_b_core(jsonb,uuid)'',\n       ''public.hotel_v2_admin_apply_workspace_plan_admin_b_core(jsonb,uuid)'',\n       ''public.hotel_v2_admin_apply_calendar_plan_admin_c_core(jsonb,uuid)'',\n       ''public.hotel_v2_admin_apply_workspace_plan_admin_c_core(jsonb,uuid)'',\n       ''public.hotel_v2_admin_apply_h3_1_configuration_admin_c_core(jsonb,uuid)'',\n       ''public.hotel_v2_admin_apply_legacy_pricing_promotion_admin_c_core(jsonb,uuid)''\n     ]::text[]) is distinct from true\n     or exists(select 1 from jsonb_each_text(\n       v_receipt.compatibility_function_fingerprints) fingerprint(signature,value)\n       where (fingerprint.value~''^[0-9a-f]{64}$'') is distinct from true)\n     or not exists(select 1 from pg_class relation\n       where relation.oid=\n         ''hotels_v2_private.hotel_external_calendar_activation_receipts''::regclass\n         and relation.relowner=''postgres''::regrole)\n     or (select count(*) from pg_attribute attribute\n       where attribute.attrelid=\n         ''hotels_v2_private.hotel_external_calendar_activation_receipts''::regclass\n         and attribute.attnum>0 and not attribute.attisdropped)<>4\n     or exists(select 1 from (values\n        (1::smallint,''id'',''smallint'',true,null::text),\n        (2::smallint,''site_settings_without_external_fingerprint'',''text'',true,null::text),\n        (3::smallint,''compatibility_function_fingerprints'',''jsonb'',true,null::text),\n        (4::smallint,''created_at'',''timestamp with time zone'',true,''clock_timestamp()'')\n       ) expected(attnum,attname,type_name,not_null,default_expression)\n       left join pg_attribute attribute on attribute.attrelid=\n         ''hotels_v2_private.hotel_external_calendar_activation_receipts''::regclass\n         and attribute.attnum=expected.attnum and not attribute.attisdropped\n       left join pg_attrdef default_row on default_row.adrelid=attribute.attrelid\n         and default_row.adnum=attribute.attnum\n       where attribute.attrelid is null\n         or attribute.attname is distinct from expected.attname\n         or format_type(attribute.atttypid,attribute.atttypmod)\n           is distinct from expected.type_name\n         or attribute.attnotnull is distinct from expected.not_null\n         or attribute.attidentity is distinct from ''''\n         or attribute.attgenerated is distinct from ''''\n         or pg_get_expr(default_row.adbin,default_row.adrelid)\n           is distinct from expected.default_expression)\n     or (select count(*) from pg_constraint constraint_row where\n       constraint_row.conrelid=\n         ''hotels_v2_private.hotel_external_calendar_activation_receipts''::regclass)<>4\n     or (select count(*) f