esc,tier.id\n    limit 1\n  ) room_tier on true\n  left join lateral (\n    select (legacy.value->>''price_per_night'')::numeric nightly_rate\n    from public.hotels hotel\n    cross join lateral jsonb_array_elements(hotel.pricing_tiers->''rules'') legacy(value)\n    where hotel.id=p_hotel_id\n      and (legacy.value->>''persons'')::integer=greatest(item.guest_count,2)\n      and (legacy.value->>''min_nights'')::integer<=duration.nights\n    order by (legacy.value->>''min_nights'')::integer desc\n    limit 1\n  ) legacy_tier on true\n),\ncomparisons as (\n  select priced.guest_count,priced.allocation_mode,priced.option_number,priced.nights,\n    max(priced.threshold_nights)::integer threshold_nights,\n    case when count(*)=1 then max(priced.resolved_pricing_guest_count)::integer else null end priced_occupancy,\n    jsonb_agg(jsonb_build_object(\n      ''room_type_id'',priced.room_type_id,\n      ''room_rate_id'',priced.room_rate_id,\n      ''pricing_guest_count'',priced.resolved_pricing_guest_count,\n      ''nightly_rate'',priced.nightly_rate\n    ) order by priced.sort_order,priced.item_id) room_nightly_rates,\n    max(priced.legacy_nightly_rate) legacy_nightly_rate,\n    sum(priced.nightly_rate) room_rate_sum\n  from priced_rows priced\n  group by priced.guest_count,priced.allocation_mode,priced.option_number,priced.nights\n),\noption_rows as (\n  select distinct item.guest_count,item.allocation_mode,item.option_number\n  from numbered_items item\n),\noptions as (\n  select option_row.guest_count,option_row.allocation_mode,option_row.option_number,\n    (select jsonb_agg(jsonb_build_object(\n      ''room_type_id'',item.room_type_id,\n      ''room_rate_id'',item.room_rate_id,\n      ''room_name'',item.room_name,\n      ''allocated_guest_count'',item.allocated_guest_count,\n      ''pricing_guest_count'',item.pricing_guest_count,\n      ''units_required'',item.units_required\n    ) order by item.sort_order,item.item_id)\n      from numbered_items item\n      where item.guest_count=option_row.guest_count\n        and item.option_number=option_row.option_number\n    ) allocation,\n    (select jsonb_agg(jsonb_build_object(\n      ''nights'',comparison.nights,\n      ''threshold_nights'',comparison.threshold_nights,\n      ''requested_guest_count'',comparison.guest_count,\n      ''priced_occupancy'',comparison.priced_occupancy,\n      ''room_nightly_rates'',comparison.room_nightly_rates,\n      ''legacy_nightly_rate'',comparison.legacy_nightly_rate,\n      ''room_rate_sum'',comparison.room_rate_sum,\n      ''stay_total'',comparison.room_rate_sum*comparison.nights,\n      ''currency'',''EUR''\n    ) order by comparison.nights)\n      from comparisons comparison\n      where comparison.guest_count=option_row.guest_count\n        and comparison.option_number=option_row.option_number\n    ) nightly_comparisons\n  from option_rows option_row\n),\npreview_rows as (\n  select requested.guest_count,matched.allocation_mode,\n    coalesce(jsonb_agg(jsonb_build_object(\n      ''allocation'',options.allocation,\n      ''nightly_comparisons'',options.nightly_comparisons\n    ) order by options.option_number) filter(where options.option_number is not null),''[]''::jsonb) options\n  from requested\n  left join matched_rules matched on matched.guest_count=requested.guest_count\n  left join options on options.guest_count=requested.guest_count\n  group by requested.guest_count,matched.allocation_mode\n)\nselect coalesce(jsonb_agg(jsonb_build_object(\n  ''guest_count'',preview.guest_count,\n  ''allocation_mode'',preview.allocation_mode,\n  ''options'',preview.options\n) order by preview.guest_count),''[]''::jsonb)\nfrom preview_rows preview;\n","result_type":"jsonb","security_definer":false,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"text, uuid","config":["search_path=pg_catalog"],"definition":"CREATE OR REPLACE FUNCTION public.hotel_v2_h3_1p_expected_pricing_guest_count(p_rule_code text, p_room_type_id uuid)\n RETURNS smallint\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''pg_catalog''\nAS $function$\n  select case\n    when p_rule_code=''guests-5-bundle'' and p_room_type_id in (\n      ''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,\n      ''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid\n    ) then 2\n    when p_rule_code=''guests-6-bundle'' and p_room_type_id in (\n      ''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,\n      ''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid\n    ) then 3\n    when p_rule_code in (''guests-7-bundle'',''guests-8-bundle'') and p_room_type_id in (\n      ''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,\n      ''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid\n    ) then 4\n    else null\n  end::smallint;\n$function$\n","identity":"hotel_v2_h3_1p_expected_pricing_guest_count(text,uuid)","owner":"postgres","prosrc":"\n  select case\n    when p_rule_code=''guests-5-bundle'' and p_room_type_id in (\n      ''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,\n      ''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid\n    ) then 2\n    when p_rule_code=''guests-6-bundle'' and p_room_type_id in (\n      ''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,\n      ''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid\n    ) then 3\n    when p_rule_code in (''guests-7-bundle'',''guests-8-bundle'') and p_room_type_id in (\n      ''b4ef504f-cdeb-4e3c-a54d-932146ef4e94''::uuid,\n      ''825c01b7-9f82-492a-9c81-9b1d5cd7acd3''::uuid\n    ) then 4\n    else null\n  end::smallint;\n","result_type":"smallint","security_definer":false,"volatility":"i"},{"acl":["postgres=X/postgres"],"argument_types":"uuid","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION public.hotel_v2_h3_1p_parity_snapshot(p_hotel_id uuid)\n RETURNS jsonb\n LANGUAGE sql\n STABLE\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nwith preview as (\n  select public.hotel_v2_h3_1p_allocation_preview(p_hotel_id) value\n), comparisons as (\n  select (entry.value->>''guest_count'')::integer guest_count,\n    comparison.value comparison\n  from preview\n  cross join lateral jsonb_array_elements(preview.value) entry(value)\n  cross join lateral jsonb_array_elements(entry.value->''options'') option(value)\n  cross join lateral jsonb_array_elements(option.value->''nightly_comparisons'') comparison(value)\n  -- The two customer-choice rooms share the exact same reviewed schedule.\n  -- Count only the first identical option in the parity oracle.\n  where entry.value->>''allocation_mode''<>''customer_choice''\n     or option.value=(entry.value->''options'')->0\n), normalized as (\n  select guest_count,\n    (comparison->>''nights'')::integer nights,\n    (comparison->>''legacy_nightly_rate'')::numeric legacy_nightly_rate,\n    (comparison->>''room_rate_sum'')::numeric room_rate_sum,\n    (comparison->>''stay_total'')::numeric stay_total\n  from comparisons\n  where guest_count between 2 and 8\n), summary as (\n  select count(*)::integer total_case_count,\n    count(*) filter(where nights between 2 and 10)::integer threshold_case_count,\n    count(*) filter(where nights=14)::integer long_stay_case_count,\n    count(*) filter(where room_rate_sum is distinct from legacy_nightly_rate\n      or stay_total is distinct from legacy_nightly_rate*nights)::integer total_mismatch_count,\n    count(*) filter(where nights between 2 and 10 and (\n      room_rate_sum is distinct from legacy_nightly_rate\n      or stay_total is distinct from legacy_nightly_rate*nights\n    ))::integer threshold_mismatch_count,\n    count(*) filter(where nights=14 and (\n      room_rate_sum is distinct from legacy_nightly_rate\n      or stay_total is distinct from legacy_nightly_rate*nights\n    ))::integer long_stay_mismatch_count,\n    md5(coalesce(string_agg(jsonb_build_object(\n      ''guest_count'',guest_count,''nights'',nights,\n      ''legacy_nightly_rate'',legacy_nightly_rate,\n      ''room_rate_sum'',room_rate_sum,''stay_total'',stay_total\n    )::text,''|'' order by guest_count,nights),'''')) fingerprint\n  from normalized\n)\nselect jsonb_build_object(\n  ''threshold_case_count'',threshold_case_count,\n  ''threshold_mismatch_count'',threshold_mismatch_count,\n  ''long_stay_case_count'',long_stay_case_count,\n  ''long_stay_mismatch_count'',long_stay_mismatch_count,\n  ''total_case_count'',total_case_count,\n  ''total_mismatch_count'',total_mismatch_count,\n  ''fingerprint'',fingerprint\n)\nfrom summary;\n$function$\n","identity":"hotel_v2_h3_1p_parity_snapshot(uuid)","owner":"postgres","prosrc":"\nwith preview as (\n  select public.hotel_v2_h3_1p_allocation_preview(p_hotel_id) value\n), comparisons as (\n  select (entry.value->>''guest_count'')::integer guest_count,\n    comparison.value comparison\n  from preview\n  cross join lateral jsonb_array_elements(preview.value) entry(value)\n  cross join lateral jsonb_array_elements(entry.value->''options'') option(value)\n  cross join lateral jsonb_array_elements(option.value->''nightly_comparisons'') comparison(value)\n  -- The two customer-choice rooms share the exact same reviewed schedule.\n  -- Count only the first identical option in the parity oracle.\n  where entry.value->>''allocation_mode''<>''customer_choice''\n     or option.value=(entry.value->''options'')->0\n), normalized as (\n  select guest_count,\n    (comparison->>''nights'')::integer nights,\n    (comparison->>''legacy_nightly_rate'')::numeric legacy_nightly_rate,\n    (comparison->>''room_rate_sum'')::numeric room_rate_sum,\n    (comparison->>''stay_total'')::numeric stay_total\n  from comparisons\n  where guest_count between 2 and 8\n), summary as (\n  select count(*)::integer total_case_count,\n    count(*) filter(where nights between 2 and 10)::integer threshold_case_count,\n    count(*) filter(where nights=14)::integer long_stay_case_count,\n    count(*) filter(where room_rate_sum is distinct from legacy_nightly_rate\n      or stay_total is distinct from legacy_nightly_rate*nights)::integer total_mismatch_count,\n    count(*) filter(where nights between 2 and 10 and (\n      room_rate_sum is distinct from legacy_nightly_rate\n      or stay_total is distinct from legacy_nightly_rate*nights\n    ))::integer threshold_mismatch_count,\n    count(*) filter(where nights=14 and (\n      room_rate_sum is distinct from legacy_nightly_rate\n      or stay_total is distinct from legacy_nightly_rate*nights\n    ))::integer long_stay_mismatch_count,\n    md5(coalesce(string_agg(jsonb_build_object(\n      ''guest_count'',guest_count,''nights'',nights,\n      ''legacy_nightly_rate'',legacy_nightly_rate,\n      ''room_rate_sum'',room_rate_sum,''stay_total'',stay_total\n    )::text,''|'' order by guest_count,nights),'''')) fingerprint\n  from normalized\n)\nselect jsonb_build_object(\n  ''threshold_case_count'',threshold_case_count,\n  ''threshold_mismatch_count'',threshold_mismatch_count,\n  ''long_stay_case_count'',long_stay_case_count,\n  ''long_stay_mismatch_count'',long_stay_mismatch_count,\n  ''total_case_count'',total_case_count,\n  ''total_mismatch_count'',total_mismatch_count,\n  ''fingerprint'',fingerprint\n)\nfrom summary;\n","result_type":"jsonb","security_definer":false,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"jsonb","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION public.hotel_v2_h3_2a_jsonb_is_pii_free(p_value jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n IMMUTABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\ndeclare\n  v_key text;\n  v_child jsonb;\nbegin\n  if p_value is null then\n    return true;\n  end if;\n\n  if jsonb_typeof(p_value) = ''object'' then\n    for v_key, v_child in select key, value from jsonb_each(p_value)\n    loop\n      if lower(v_key) ~ ''(customer|guest|contact|email|phone|password|secret|token|authorization|iban|bank_account|card_number|raw_request|request_body|reviewed_plan)'' then\n        return false;\n      end if;\n      if not public.hotel_v2_h3_2a_jsonb_is_pii_free(v_child) then\n        return false;\n      end if;\n    end loop;\n  elsif jsonb_typeof(p_value) = ''array'' then\n    for v_child in select value from jsonb_array_elements(p_value)\n    loop\n      if not public.hotel_v2_h3_2a_jsonb_is_pii_free(v_child) then\n        return false;\n      end if;\n    end loop;\n  end if;\n\n  return true;\nend\n$function$\n","identity":"hotel_v2_h3_2a_jsonb_is_pii_free(jsonb)","owner":"postgres","prosrc":"\ndeclare\n  v_key text;\n  v_child jsonb;\nbegin\n  if p_value is null then\n    return true;\n  end if;\n\n  if jsonb_typeof(p_value) = ''object'' then\n    for v_key, v_child in select key, value from jsonb_each(p_value)\n    loop\n      if lower(v_key) ~ ''(customer|guest|contact|email|phone|password|secret|token|authorization|iban|bank_account|card_number|raw_request|request_body|reviewed_plan)'' then\n        return false;\n      end if;\n      if not public.hotel_v2_h3_2a_jsonb_is_pii_free(v_child) then\n        return false;\n      end if;\n    end loop;\n  elsif jsonb_typeof(p_value) = ''array'' then\n    for v_child in select value from jsonb_array_elements(p_value)\n    loop\n      if not public.hotel_v2_h3_2a_jsonb_is_pii_free(v_child) then\n        return false;\n      end if;\n    end loop;\n  end if;\n\n  return true;\nend\n","result_type":"boolean","security_definer":true,"volatility":"i"},{"acl":["postgres=X/postgres"],"argument_types":"uuid","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION public.hotel_v2_h3_2a_permissions_snapshot(p_assignment_id uuid)\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\n  select case when permission.assignment_id is null then\n    jsonb_build_object(\n      ''exists'', false,\n      ''version'', 0,\n      ''updated_at'', null,\n      ''has_mutation_capability'', false,\n      ''capabilities'', jsonb_build_object(\n        ''edit_property_content'', false,\n        ''edit_property_photos'', false,\n        ''edit_room_content'', false,\n        ''edit_room_photos'', false,\n        ''create_rooms'', false,\n        ''edit_room_structure'', false,\n        ''manage_prices'', false,\n        ''manage_availability'', false,\n        ''process_bookings'', false,\n        ''request_booking_changes'', false,\n        ''view_payment_status'', false,\n        ''initiate_stripe_onboarding'', false\n      )\n    )\n  else\n    jsonb_build_object(\n      ''exists'', true,\n      ''version'', permission.version,\n      ''updated_at'', permission.updated_at,\n      ''has_mutation_capability'', permission.has_mutation_capability,\n      ''capabilities'', jsonb_build_object(\n        ''edit_property_content'', permission.edit_property_content,\n        ''edit_property_photos'', permission.edit_property_photos,\n        ''edit_room_content'', permission.edit_room_content,\n        ''edit_room_photos'', permission.edit_room_photos,\n        ''create_rooms'', permission.create_rooms,\n        ''edit_room_structure'', permission.edit_room_structure,\n        ''manage_prices'', permission.manage_prices,\n        ''manage_availability'', permission.manage_availability,\n        ''process_bookings'', permission.process_bookings,\n        ''request_booking_changes'', permission.request_booking_changes,\n        ''view_payment_status'', permission.view_payment_status,\n        ''initiate_stripe_onboarding'', permission.initiate_stripe_onboarding\n      )\n    )\n  end\n  from (select 1) singleton\n  left join public.hotel_partner_hotel_permissions permission\n    on permission.assignment_id = p_assignment_id;\n$function$\n","identity":"hotel_v2_h3_2a_permissions_snapshot(uuid)","owner":"postgres","prosrc":"\n  select case when permission.assignment_id is null then\n    jsonb_build_object(\n      ''exists'', false,\n      ''version'', 0,\n      ''updated_at'', null,\n      ''has_mutation_capability'', false,\n      ''capabilities'', jsonb_build_object(\n        ''edit_property_content'', false,\n        ''edit_property_photos'', false,\n        ''edit_room_content'', false,\n        ''edit_room_photos'', false,\n        ''create_rooms'', false,\n        ''edit_room_structure'', false,\n        ''manage_prices'', false,\n        ''manage_availability'', false,\n        ''process_bookings'', false,\n        ''request_booking_changes'', false,\n        ''view_payment_status'', false,\n        ''initiate_stripe_onboarding'', false\n      )\n    )\n  else\n    jsonb_build_object(\n      ''exists'', true,\n      ''version'', permission.version,\n      ''updated_at'', permission.updated_at,\n      ''has_mutation_capability'', permission.has_mutation_capability,\n      ''capabilities'', jsonb_build_object(\n        ''edit_property_content'', permission.edit_property_content,\n        ''edit_property_photos'', permission.edit_property_photos,\n        ''edit_room_content'', permission.edit_room_content,\n        ''edit_room_photos'', permission.edit_room_photos,\n        ''create_rooms'', permission.create_rooms,\n        ''edit_room_structure'', permission.edit_room_structure,\n        ''manage_prices'', permission.manage_prices,\n        ''manage_availability'', permission.manage_availability,\n        ''process_bookings'', permission.process_bookings,\n        ''request_booking_changes'', permission.request_booking_changes,\n        ''view_payment_status'', permission.view_payment_status,\n        ''initiate_stripe_onboarding'', permission.initiate_stripe_onboarding\n      )\n    )\n  end\n  from (select 1) singleton\n  left join public.hotel_partner_hotel_permissions permission\n    on permission.assignment_id = p_assignment_id;\n","result_type":"jsonb","security_definer":true,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"jsonb","config":["search_path=pg_catalog"],"definition":"CREATE OR REPLACE FUNCTION public.hotel_v2_h3_2b_hash(p_value jsonb)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''pg_catalog''\nAS $function$select encode(extensions.digest(convert_to(p_value::text,''UTF8''),''sha256''),''hex'')$function$\n","identity":"hotel_v2_h3_2b_hash(jsonb)","owner":"postgres","prosrc":"select encode(extensions.digest(convert_to(p_value::text,''UTF8''),''sha256''),''hex'')","result_type":"text","security_definer":false,"volatility":"i"},{"acl":["postgres=X/postgres"],"argument_types":"","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION public.hotel_v2_partner_workspace_function_lineage_is_exact()\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\ndeclare\n  c_signature constant text:=''public.hotel_v2_partner_get_workspace(uuid,uuid,date,date)'';\n  c_old constant text:=''where draft.assignment_id=(v_access->>''''assignment_id'''')::uuid;'';\n  c_new constant text:=''where draft.assignment_id=(v_access->>''''assignment_id'''')::uuid''\n    ||E''\\n    and draft.status=''''pending_admin_review'''';'';\n  v_activation hotels_v2_private.hotel_external_calendar_activation_receipts%rowtype;\n  v_owner public.hotel_admin_availability_foundation_evolution_receipts%rowtype;\n  v_receipt public.hotel_partner_property_proposal_foundation_receipts%rowtype;\n  v_current jsonb; v_source text; v_oid oid;\nbegin\n  if (select count(*) from hotels_v2_private.hotel_external_calendar_activation_receipts)<>1\n     or (select count(*) from public.hotel_partner_workspace_foundation_receipts)<>1\n     or (select count(*) from public.hotel_admin_availability_foundation_evolution_receipts)<>1\n     or (select count(*) from public.hotel_admin_availability_foundation_receipts)<>1\n     or (select count(*) from public.hotel_partner_property_proposal_foundation_receipts)<>1 then\n    return false;\n  end if;\n  select * into strict v_activation\n    from hotels_v2_private.hotel_external_calendar_activation_receipts where id=1;\n  select * into strict v_owner\n 