   (comparison.value->>''threshold_nights'')::integer threshold_nights,\n    (comparison.value->>''legacy_nightly_rate'')::numeric legacy_nightly_rate,\n    (comparison.value->>''room_rate_sum'')::numeric room_rate_sum,\n    (comparison.value->>''stay_total'')::numeric stay_total,\n    comparison.value->''room_nightly_rates'' room_nightly_rates,\n    option.value->''allocation'' allocation\n  from preview\n  cross join lateral jsonb_array_elements(preview.value) entry(value)\n  cross join lateral jsonb_array_elements(entry.value->''options'')\n    with ordinality option(value,ordinality)\n  cross join lateral jsonb_array_elements(\n    option.value->''nightly_comparisons'') comparison(value)\n), checked as (\n  select case_row.*,\n    coalesce((select bool_and(\n      authority.target_tier_id is not null\n      and authority.current_nightly_rate=(room.value->>''nightly_rate'')::numeric\n      and authority.current_target_version=tier.version\n      and tier.nightly_rate=authority.current_nightly_rate\n      and tier.is_active)\n      from jsonb_array_elements(case_row.room_nightly_rates) room(value)\n      left join public.hotel_seven_arches_independent_pricing_authority authority\n        on authority.room_rate_id=(room.value->>''room_rate_id'')::uuid\n        and authority.guest_count=(room.value->>''pricing_guest_count'')::smallint\n        and authority.threshold_nights=case_row.threshold_nights\n      left join public.hotel_pricing_schedule_occupancy_tiers tier\n        on tier.id=authority.target_tier_id),false) authority_exact,\n    coalesce((select bool_and(\n      (room.value->>''pricing_guest_count'')::integer=2)\n      from jsonb_array_elements(case_row.room_nightly_rates) room(value)),false)\n      guest_one_floor_exact,\n    (select sum((item.value->>''units_required'')::integer)\n      from jsonb_array_elements(case_row.allocation) item(value)) allocated_room_count\n  from cases case_row\n), summary as (\n  select\n    count(*) filter(where requested_guest_count between 2 and 8)::integer\n      core_case_count,\n    count(*) filter(where requested_guest_count between 2 and 8 and (\n      not authority_exact\n      or stay_total is distinct from room_rate_sum*nights\n      or (requested_guest_count between 5 and 8\n        and room_rate_sum is distinct from legacy_nightly_rate)))::integer\n      core_mismatch_count,\n    count(*) filter(where requested_guest_count=1)::integer guest_one_case_count,\n    count(*) filter(where requested_guest_count=1 and (\n      not authority_exact or not guest_one_floor_exact\n      or stay_total is distinct from room_rate_sum*nights))::integer\n      guest_one_mismatch_count,\n    count(*)::integer total_case_count,\n    md5(coalesce(string_agg(jsonb_build_object(\n      ''requested_guest_count'',requested_guest_count,\n      ''option_number'',option_number,''nights'',nights,\n      ''threshold_nights'',threshold_nights,\n      ''legacy_nightly_rate'',legacy_nightly_rate,\n      ''room_rate_sum'',room_rate_sum,''stay_total'',stay_total,\n      ''room_nightly_rates'',room_nightly_rates,''allocation'',allocation,\n      ''authority_exact'',authority_exact,\n      ''guest_one_floor_exact'',guest_one_floor_exact,\n      ''commission_total'',allocated_room_count*10*nights,\n      ''partner_net'',stay_total-allocated_room_count*10*nights)::text,\n      ''|'' order by requested_guest_count,option_number,nights),'''')) fingerprint\n  from checked\n)\nselect jsonb_build_object(\n  ''contract_version'',''hotels_v2_seven_arches_reviewed_pricing_oracle_v1'',\n  ''core_case_count'',core_case_count,\n  ''core_mismatch_count'',core_mismatch_count,\n  ''guest_one_case_count'',guest_one_case_count,\n  ''guest_one_mismatch_count'',guest_one_mismatch_count,\n  ''total_case_count'',total_case_count,\n  ''fingerprint'',fingerprint)\nfrom summary;\n","result_type":"jsonb","security_definer":true,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION hotels_guest_policy_private.assert_exact()\n RETURNS void\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE c hotels_guest_policy_private.receipt%rowtype; b record;\nBEGIN\n SELECT * INTO STRICT c FROM hotels_guest_policy_private.receipt WHERE id=1;\n IF (SELECT count(*) FROM hotels_guest_policy_private.receipt)<>1\n OR c.mutable_columns IS DISTINCT FROM ARRAY[''children_policy'',''minimum_child_age'']::text[]\n OR c.bindings_hash IS DISTINCT FROM (SELECT encode(sha256(convert_to(jsonb_agg(to_jsonb(x) ORDER BY signature)::text,''UTF8'')),''hex'') FROM hotels_guest_policy_private.bindings x)\n OR c.historical_foundation IS DISTINCT FROM (SELECT to_jsonb(x) FROM public.hotel_seven_arches_reviewed_pricing_foundation_receipts x WHERE id=1)\n OR c.historical_foundation_hash IS DISTINCT FROM encode(sha256(convert_to(c.historical_foundation::text,''UTF8'')),''hex'')\n THEN RAISE EXCEPTION ''hotels_114484_evidence_drift''; END IF;\n FOR b IN SELECT * FROM hotels_guest_policy_private.bindings LOOP\n  IF hotels_guest_policy_private.raw_metadata(to_regprocedure(b.signature))-0-0 IS DISTINCT FROM b.before_metadata-0-0\n   OR (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc WHERE oid=to_regprocedure(b.signature)) IS DISTINCT FROM b.after_hash\n   OR pg_get_functiondef(to_regprocedure(b.signature)) IS DISTINCT FROM replace(b.before_definition,b.before_source,b.after_source)\n  THEN RAISE EXCEPTION ''hotels_114484_bound_source_security_drift:%'',b.signature; END IF;\n END LOOP;\n IF c.helpers IS DISTINCT FROM (SELECT jsonb_object_agg(p.oid::regprocedure::text,hotels_guest_policy_private.raw_metadata(p.oid)) FROM pg_proc p WHERE p.pronamespace=''hotels_guest_policy_private''::regnamespace)\n OR c.relations IS DISTINCT FROM hotels_guest_policy_private.relation_catalog()\n OR EXISTS(SELECT 1 FROM pg_class r WHERE r.relnamespace=''hotels_guest_policy_private''::regnamespace AND r.relkind=''r'' AND (r.relowner<>''postgres''::regrole OR NOT r.relrowsecurity OR NOT r.relforcerowsecurity\n OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=r.oid)\n OR EXISTS(SELECT 1 FROM aclexplode(coalesce(r.relacl,acldefault(''r'',r.relowner))) a WHERE a.grantee<>r.relowner)\n OR (SELECT count(*) FROM pg_trigger t WHERE t.tgrelid=r.oid AND NOT t.tgisinternal AND t.tgname=''immutable'' AND t.tgenabled=''O'' AND t.tgtype=58 AND t.tgfoid=''hotels_guest_policy_private.immutable()''::regprocedure)<>1))\n THEN RAISE EXCEPTION ''hotels_114484_helper_security_drift''; END IF;\nEND $function$\n","identity":"hotels_guest_policy_private.assert_exact()","owner":"postgres","prosrc":"\nDECLARE c hotels_guest_policy_private.receipt%rowtype; b record;\nBEGIN\n SELECT * INTO STRICT c FROM hotels_guest_policy_private.receipt WHERE id=1;\n IF (SELECT count(*) FROM hotels_guest_policy_private.receipt)<>1\n OR c.mutable_columns IS DISTINCT FROM ARRAY[''children_policy'',''minimum_child_age'']::text[]\n OR c.bindings_hash IS DISTINCT FROM (SELECT encode(sha256(convert_to(jsonb_agg(to_jsonb(x) ORDER BY signature)::text,''UTF8'')),''hex'') FROM hotels_guest_policy_private.bindings x)\n OR c.historical_foundation IS DISTINCT FROM (SELECT to_jsonb(x) FROM public.hotel_seven_arches_reviewed_pricing_foundation_receipts x WHERE id=1)\n OR c.historical_foundation_hash IS DISTINCT FROM encode(sha256(convert_to(c.historical_foundation::text,''UTF8'')),''hex'')\n THEN RAISE EXCEPTION ''hotels_114484_evidence_drift''; END IF;\n FOR b IN SELECT * FROM hotels_guest_policy_private.bindings LOOP\n  IF hotels_guest_policy_private.raw_metadata(to_regprocedure(b.signature))-0-0 IS DISTINCT FROM b.before_metadata-0-0\n   OR (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc WHERE oid=to_regprocedure(b.signature)) IS DISTINCT FROM b.after_hash\n   OR pg_get_functiondef(to_regprocedure(b.signature)) IS DISTINCT FROM replace(b.before_definition,b.before_source,b.after_source)\n  THEN RAISE EXCEPTION ''hotels_114484_bound_source_security_drift:%'',b.signature; END IF;\n END LOOP;\n IF c.helpers IS DISTINCT FROM (SELECT jsonb_object_agg(p.oid::regprocedure::text,hotels_guest_policy_private.raw_metadata(p.oid)) FROM pg_proc p WHERE p.pronamespace=''hotels_guest_policy_private''::regnamespace)\n OR c.relations IS DISTINCT FROM hotels_guest_policy_private.relation_catalog()\n OR EXISTS(SELECT 1 FROM pg_class r WHERE r.relnamespace=''hotels_guest_policy_private''::regnamespace AND r.relkind=''r'' AND (r.relowner<>''postgres''::regrole OR NOT r.relrowsecurity OR NOT r.relforcerowsecurity\n OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=r.oid)\n OR EXISTS(SELECT 1 FROM aclexplode(coalesce(r.relacl,acldefault(''r'',r.relowner))) a WHERE a.grantee<>r.relowner)\n OR (SELECT count(*) FROM pg_trigger t WHERE t.tgrelid=r.oid AND NOT t.tgisinternal AND t.tgname=''immutable'' AND t.tgenabled=''O'' AND t.tgtype=58 AND t.tgfoid=''hotels_guest_policy_private.immutable()''::regprocedure)<>1))\n THEN RAISE EXCEPTION ''hotels_114484_helper_security_drift''; END IF;\nEND ","result_type":"void","security_definer":true,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"oid","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION hotels_guest_policy_private.original_definition(p_oid oid)\n RETURNS text\n LANGUAGE plpgsql\n STABLE STRICT SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE d text; BEGIN\n PERFORM hotels_guest_policy_private.original_source(p_oid);\n SELECT before_definition INTO d FROM hotels_guest_policy_private.bindings WHERE to_regprocedure(signature)=p_oid;\n RETURN coalesce(d,pg_get_functiondef(p_oid));\nEND $function$\n","identity":"hotels_guest_policy_private.original_definition(oid)","owner":"postgres","prosrc":"\nDECLARE d text; BEGIN\n PERFORM hotels_guest_policy_private.original_source(p_oid);\n SELECT before_definition INTO d FROM hotels_guest_policy_private.bindings WHERE to_regprocedure(signature)=p_oid;\n RETURN coalesce(d,pg_get_functiondef(p_oid));\nEND ","result_type":"text","security_definer":true,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"oid","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION hotels_guest_policy_private.original_source(p_oid oid)\n RETURNS text\n LANGUAGE plpgsql\n STABLE STRICT SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE b hotels_guest_policy_private.bindings%rowtype; s text;\nBEGIN\n SELECT * INTO b FROM hotels_guest_policy_private.bindings WHERE to_regprocedure(signature)=p_oid;\n SELECT prosrc INTO s FROM pg_proc WHERE oid=p_oid;\n IF b.signature IS NOT NULL THEN\n  -- Validate this exact binding, not the whole dependency graph per catalog row.\n  -- historical_hotel/assert_exact additionally validates the complete successor.\n  IF encode(sha256(convert_to(s,''UTF8'')),''hex'') IS DISTINCT FROM b.after_hash\n   OR hotels_guest_policy_private.raw_metadata(p_oid)-0-0 IS DISTINCT FROM b.before_metadata-0-0\n   OR encode(sha256(convert_to(b.before_source,''UTF8'')),''hex'') IS DISTINCT FROM b.before_metadata->>0\n   OR pg_get_functiondef(p_oid) IS DISTINCT FROM replace(b.before_definition,b.before_source,b.after_source)\n  THEN RAISE EXCEPTION ''hotels_114484_bound_source_security_drift''; END IF;\n  RETURN b.before_source;\n END IF;\n RETURN s;\nEND $function$\n","identity":"hotels_guest_policy_private.original_source(oid)","owner":"postgres","prosrc":"\nDECLARE b hotels_guest_policy_private.bindings%rowtype; s text;\nBEGIN\n SELECT * INTO b FROM hotels_guest_policy_private.bindings WHERE to_regprocedure(signature)=p_oid;\n SELECT prosrc INTO s FROM pg_proc WHERE oid=p_oid;\n IF b.signature IS NOT NULL THEN\n  -- Validate this exact binding, not the whole dependency graph per catalog row.\n  -- historical_hotel/assert_exact additionally validates the complete successor.\n  IF encode(sha256(convert_to(s,''UTF8'')),''hex'') IS DISTINCT FROM b.after_hash\n   OR hotels_guest_policy_private.raw_metadata(p_oid)-0-0 IS DISTINCT FROM b.before_metadata-0-0\n   OR encode(sha256(convert_to(b.before_source,''UTF8'')),''hex'') IS DISTINCT FROM b.before_metadata->>0\n   OR pg_get_functiondef(p_oid) IS DISTINCT FROM replace(b.before_definition,b.before_source,b.after_source)\n  THEN RAISE EXCEPTION ''hotels_114484_bound_source_security_drift''; END IF;\n  RETURN b.before_source;\n END IF;\n RETURN s;\nEND ","result_type":"text","security_definer":true,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"oid","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION hotels_guest_policy_private.raw_metadata(p_oid oid)\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$SELECT jsonb_build_array(encode(sha256(convert_to(p.prosrc,''UTF8'')),''hex''),\n encode(sha256(convert_to(pg_get_functiondef(p.oid),''UTF8'')),''hex''),\n pg_get_userbyid(p.proowner),(CASE WHEN p.proacl IS NULL THEN NULL ELSE ARRAY(SELECT entry::text FROM unnest(p.proacl) AS acl(entry) ORDER BY entry::text COLLATE \"C\") END)::text,p.proconfig,p.provolatile,p.prosecdef,\n p.proleakproof,p.proisstrict,p.proretset,l.lanname)\n FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=p_oid$function$\n","identity":"hotels_guest_policy_private.raw_metadata(oid)","owner":"postgres","prosrc":"SELECT jsonb_build_array(encode(sha256(convert_to(p.prosrc,''UTF8'')),''hex''),\n encode(sha256(convert_to(pg_get_functiondef(p.oid),''UTF8'')),''hex''),\n pg_get_userbyid(p.proowner),(CASE WHEN p.proacl IS NULL THEN NULL ELSE ARRAY(SELECT entry::text FROM unnest(p.proacl) AS acl(entry) ORDER BY entry::text COLLATE \"C\") END)::text,p.proconfig,p.provolatile,p.prosecdef,\n p.proleakproof,p.proisstrict,p.proretset,l.lanname)\n FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=p_oid","result_type":"jsonb","security_definer":true,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION hotels_guest_policy_private.relation_catalog()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nSELECT jsonb_build_object(''schema'',(SELECT jsonb_build_array(nspowner,nspacl) FROM pg_namespace WHERE nspname=''hotels_guest_policy_private''),\n''relations'',(SELECT jsonb_agg(jsonb_build_object(''name'',r.relname,''kind'',r.relkind,''owner'',r.relowner,''rls'',r.relrowsecurity,''force'',r.relforcerowsecurity,''acl'',r.relacl,\n''columns'',(SELECT jsonb_agg(jsonb_build_array(attname,atttypid,atttypmod,attnotnull) ORDER BY attnum) FROM pg_attribute WHERE attrelid=r.oid AND attnum>0 AND NOT attisdropped),\n''constraints'',(SELECT jsonb_agg(pg_get_constraintdef(oid) ORDER BY conname) FROM pg_constraint WHERE conrelid=r.oid),\n''policies'',(SELECT jsonb_agg(to_jsonb(p)-''oid''-''polrelid'' ORDER BY polname) FROM pg_policy p WHERE polrelid=r.oid),\n''triggers'',(SELECT jsonb_agg(jsonb_build_array(tgname,tgenabled,pg_get_triggerdef(oid)) ORDER BY tgname) FROM pg_trigger WHERE tgrelid=r.oid AND NOT tgisinternal)) ORDER BY r.relname)\nFROM pg_class r WHERE r.relnamespace=''hotels_guest_policy_private''::regnamespace AND r.relkind IN(''r'',''p'',''v'',''m'',''f'')))\n$function$\n","identity":"hotels_guest_policy_private.relation_catalog()","owner":"postgres","prosrc":"\nSELECT jsonb_build_object(''schema'',(SELECT jsonb_build_array(nspowner,nspacl) FROM pg_namespace WHERE nspname=''hotels_guest_policy_private''),\n''relations'',(SELECT jsonb_agg(jsonb_build_object(''name'',r.relname,''kind'',r.relkind,''owner'',r.relowner,''rls'',r.relrowsecurity,''force'',r.relforcerowsecurity,''acl'',r.relacl,\n''columns'',(SELECT jsonb_agg(jsonb_build_array(attname,atttypid,atttypmod,attnotnull) ORDER BY attnum) FROM pg_attribute WHERE attrelid=r.oid AND attnum>0 AND NOT attisdropped),\n''constraints'',(SELECT jsonb_agg(pg_get_constraintdef(oid) ORDER BY conname) FROM pg_constraint WHERE conrelid=r.oid),\n''policies'',(SELECT jsonb_agg(to_jsonb(p)-''oid''-''polrelid'' ORDER BY polname) FROM pg_policy p WHERE polrelid=r.oid),\n''triggers'',(SELECT jsonb_agg(jsonb_build_array(tgname,tgenabled,pg_get_triggerdef(oid)) ORDER BY tgname) FROM pg_trigger WHERE tgrelid=r.oid AND NOT tgisinternal)) ORDER BY r.relname)\nFROM pg_class r WHERE r.relnamespace=''hotels_guest_policy_private''::regnamespace AND r.relkind IN(''r'',''p'',''v'',''m'',''f'')))\n","result_type":"jsonb","security_definer":true,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION hotels_lifecycle_private.actual_flags()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\n SELECT jsonb_build_object(''hotel_rooms_v2_enabled'',hotel_rooms_v2_enabled,\n ''hotel_external_sync_enabled'',hotel_external_sync_enabled,''hotel_instant_booking_enabled'',hotel_instant_booking_enabled,\n ''hotel_stripe_connect_enabled'',hotel_stripe_connect_enabled) FROM public.site_settings WHERE id=1\n$function$\n","identity":"hotels_lifecycle_private.actual_flags()","owner":"postgres","prosrc":"\n SELECT jsonb_build_object(''hotel_rooms_v2_enabled'',hotel_rooms_v2_enabled,\n ''hotel_external_sync_enabled'',hotel_external_sync_enabled,''hotel_instant_booking_enabled'',hotel_instant_booking_enabled,\n ''hotel_stripe_connect_enabled'',hotel_stripe_connect_enabled) FROM public.site_settings WHERE id=1\n","result_type":"jsonb","security_definer":true,"volatility":"s"},{"acl":["postgres=X/postgres"],"argument_types":"","config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION hotels_lifecycle_private.catalog_snapshot()\n RETURNS jsonb\n LANGUAGE sql\