  encode(extensions.digest(convert_to(hotels_stripe_dto_private.predecessor_source(p.oid),''UTF8''),''sha256''),''hex''),hotels_lifecycle_private.metadata(p.oid)) ORDER BY b.signature)
  FROM hotels_lifecycle_private.bindings b LEFT JOIN pg_proc p ON p.oid=to_regprocedure(b.signature)),
 ''authorization_dependencies'',(SELECT jsonb_object_agg(r5k_catalog_proof.procedure_text(p.oid),
 jsonb_build_array(hotels_lifecycle_private.hash(to_jsonb(hotels_stripe_dto_private.predecessor_source(p.oid))),hotels_lifecycle_private.metadata(p.oid)) ORDER BY r5k_catalog_proof.procedure_text(p.oid))
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''hotel_stripe_connect_private''
 OR p.proname IN (''hotel_v2_stripe_connect_service'',''hotel_v2_admin_get_partner_stripe_onboarding_authorization'',
 ''hotel_v2_admin_set_partner_stripe_onboarding_authorization'',''hotel_v2_h2a_require_admin'',''is_current_user_admin'')),
 ''schema'',(SELECT jsonb_build_array(pg_get_userbyid(nspowner),nspacl) FROM pg_namespace WHERE nspname=''hotels_lifecycle_private''),
 ''functions'',(SELECT jsonb_object_agg(r5k_catalog_proof.procedure_text(p.oid),jsonb_build_object(''metadata'',hotels_lifecycle_private.metadata(p.oid),
 ''hash'',hotels_lifecycle_private.hash(to_jsonb(hotels_stripe_dto_private.predecessor_source(p.oid)))) ORDER BY r5k_catalog_proof.procedure_text(p.oid))
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''hotels_lifecycle_private''
 OR p.proname IN (''hotel_v2_admin_get_capability_lifecycle'',''hotel_v2_admin_set_capability_lifecycle'',''hotel_v2_attest_stripe_platform_readiness'')),
 ''relations'',(SELECT jsonb_agg(jsonb_build_object(''name'',c.relname,''owner'',pg_get_userbyid(c.relowner),''kind'',c.relkind,
 ''persistence'',c.relpersistence,''rls'',c.relrowsecurity,''force'',c.relforcerowsecurity,''acl'',c.relacl,
 ''columns'',(SELECT jsonb_agg(jsonb_build_array(a.attname,r5k_catalog_proof.type_text(a.atttypid),a.atttypmod,a.attnotnull,
 a.attidentity,a.attgenerated,r5k_catalog_proof.collation_text(a.attcollation),
 (SELECT r5k_catalog_proof.pg_get_expr(d.adbin,d.adrelid) FROM pg_attrdef d WHERE d.adrelid=a.attrelid AND d.adnum=a.attnum)) ORDER BY a.attnum)
 FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 ''constraints'',(SELECT jsonb_agg(jsonb_build_array(conname,convalidated,r5k_catalog_proof.pg_get_constraintdef(oid)) ORDER BY conname) FROM pg_constraint WHERE conrelid=c.oid),
 ''policies'',(SELECT jsonb_agg(to_jsonb(p)-''oid''-''polrelid'') FROM pg_policy p WHERE p.polrelid=c.oid),
 ''triggers'',(SELECT jsonb_agg(jsonb_build_array(t.tgname,t.tgenabled,r5k_catalog_proof.pg_get_triggerdef(t.oid)) ORDER BY t.tgname)
 FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) ORDER BY c.relname)
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN (''hotels_lifecycle_private'',''hotel_stripe_connect_private'') AND c.relkind IN (''r'',''p'')),
 ''settings_guard'',(SELECT jsonb_build_array(t.tgenabled,r5k_catalog_proof.pg_get_triggerdef(t.oid)) FROM pg_trigger t
 WHERE t.tgrelid=''public.site_settings''::regclass AND t.tgname=''hotels_capability_lifecycle_guard'')) FROM dto_guard
';

CREATE FUNCTION r5k_catalog_proof.observer_5() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS '
 SELECT jsonb_object_agg(r5k_catalog_proof.procedure_text(p.oid),jsonb_build_object(
   ''source'',hotels_lineage_private.predecessor_source_hash(p.oid),
   ''definition'',hotels_lineage_private.predecessor_definition_hash(p.oid),
   ''owner'',p.proowner::regrole::text,''language'',(SELECT lanname FROM pg_language WHERE oid=p.prolang),
   ''definer'',p.prosecdef,''volatility'',p.provolatile,''configuration'',p.proconfig,
   ''acl'',p.proacl,''leakproof'',p.proleakproof,''parallel'',p.proparallel,
   ''kind'',p.prokind,''strict'',p.proisstrict,
   ''public_execute'',has_function_privilege(0::oid,p.oid,''EXECUTE''),
   ''anon_execute'',has_function_privilege(''anon'',p.oid,''EXECUTE''),
   ''authenticated_execute'',has_function_privilege(''authenticated'',p.oid,''EXECUTE''),
   ''service_execute'',has_function_privilege(''service_role'',p.oid,''EXECUTE'')))
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname=''hotels_lineage_private'' OR p.oid IN (
   ''public.hotel_v2_seven_arches_pricing_scoped_lineage()''::regprocedure,
   ''public.hotel_v2_seven_arches_reviewed_pricing_receipt_chain_is_exact()''::regprocedure,
   ''public.hotel_v2_seven_arches_independent_pricing_topology_is_exact()''::regprocedure);
';

CREATE FUNCTION r5k_catalog_proof.observer_6() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS '
select jsonb_build_object(
  ''contract_version'',''hotels_v2_seven_arches_reviewed_pricing_catalog_v1'',
  ''relations'',(select coalesce(jsonb_agg(jsonb_build_object(
    ''name'',r5k_catalog_proof.relation_text(relation.oid),''owner'',relation.relowner::regrole::text,
    ''kind'',relation.relkind,''persistence'',relation.relpersistence,
    ''rls'',relation.relrowsecurity,''force_rls'',relation.relforcerowsecurity,
    ''acl'',to_jsonb(relation.relacl),
    ''columns'',coalesce((select jsonb_agg(jsonb_build_object(
      ''number'',attribute.attnum,''name'',attribute.attname,
      ''type'',r5k_catalog_proof.format_type(attribute.atttypid,attribute.atttypmod),
      ''not_null'',attribute.attnotnull,''identity'',attribute.attidentity,
      ''generated'',attribute.attgenerated,
      ''default'',r5k_catalog_proof.pg_get_expr(default_row.adbin,default_row.adrelid))
      order by attribute.attnum) from pg_attribute attribute
      left join pg_attrdef default_row on default_row.adrelid=attribute.attrelid
        and default_row.adnum=attribute.attnum
      where attribute.attrelid=relation.oid and attribute.attnum>0
        and not attribute.attisdropped),''[]''::jsonb),
    ''constraints'',coalesce((select jsonb_agg(jsonb_build_object(
      ''name'',constraint_row.conname,''type'',constraint_row.contype,
      ''key'',constraint_row.conkey,''foreign_relation'',case
        when constraint_row.confrelid=0 then null
        else r5k_catalog_proof.relation_text(constraint_row.confrelid) end,
      ''foreign_key'',constraint_row.confkey,
      ''deferrable'',constraint_row.condeferrable,
      ''initially_deferred'',constraint_row.condeferred,
      ''validated'',constraint_row.convalidated,
      ''no_inherit'',constraint_row.connoinherit,
      ''expression'',r5k_catalog_proof.pg_get_expr(constraint_row.conbin,constraint_row.conrelid),
      ''definition'',r5k_catalog_proof.pg_get_constraintdef(constraint_row.oid))
      order by constraint_row.conname) from pg_constraint constraint_row
      where constraint_row.conrelid=relation.oid),''[]''::jsonb),
    ''policies'',coalesce((select jsonb_agg(jsonb_build_object(
      ''name'',policy.polname,''command'',policy.polcmd,
      ''permissive'',policy.polpermissive,''roles'',policy.polroles,
      ''qual'',r5k_catalog_proof.pg_get_expr(policy.polqual,policy.polrelid),
      ''with_check'',r5k_catalog_proof.pg_get_expr(policy.polwithcheck,policy.polrelid))
      order by policy.polname) from pg_policy policy
      where policy.polrelid=relation.oid),''[]''::jsonb),
    ''triggers'',coalesce((select jsonb_agg(jsonb_build_object(
      ''name'',trigger_row.tgname,''function'',r5k_catalog_proof.procedure_text(trigger_row.tgfoid),
      ''type'',trigger_row.tgtype,''enabled'',trigger_row.tgenabled,
      ''deferrable'',trigger_row.tgdeferrable,
      ''initially_deferred'',trigger_row.tginitdeferred)
      order by trigger_row.tgname) from pg_trigger trigger_row
      where trigger_row.tgrelid=relation.oid and not trigger_row.tgisinternal),
      ''[]''::jsonb))
    order by r5k_catalog_proof.relation_text(relation.oid)),''[]''::jsonb)
    from pg_class relation where relation.oid in(
      ''public.hotel_seven_arches_reviewed_pricing_proposals''::regclass,
      ''public.hotel_seven_arches_reviewed_pricing_proposal_items''::regclass,
      ''public.hotel_seven_arches_reviewed_pricing_admin_reviews''::regclass,
      ''public.hotel_seven_arches_reviewed_pricing_transaction_context''::regclass,
      ''public.hotel_seven_arches_reviewed_pricing_foundation_receipts''::regclass,
      ''public.hotel_seven_arches_reviewed_pricing_evolution_receipts''::regclass,
      ''public.hotel_seven_arches_independent_pricing_authority''::regclass,
      ''public.hotel_seven_arches_independent_pricing_topology_receipts''::regclass,
      ''public.hotel_seven_arches_independent_pricing_evolution_receipts''::regclass)),
  ''functions'',(select coalesce(jsonb_agg(jsonb_build_object(
    ''signature'',r5k_catalog_proof.procedure_text(procedure_row.oid),
    ''owner'',procedure_row.proowner::regrole::text,''language'',language.lanname,
    ''volatility'',procedure_row.provolatile,''security_definer'',procedure_row.prosecdef,
    ''config'',procedure_row.proconfig,''acl'',to_jsonb(procedure_row.proacl),
    ''public_execute'',has_function_privilege(0::oid,procedure_row.oid,''EXECUTE''),
    ''anon_execute'',has_function_privilege(''anon'',procedure_row.oid,''EXECUTE''),
    ''authenticated_execute'',has_function_privilege(
      ''authenticated'',procedure_row.oid,''EXECUTE''),
    ''service_execute'',has_function_privilege(''service_role'',procedure_row.oid,''EXECUTE''),
    ''source_hash'',hotels_lineage_private.predecessor_definition_hash(procedure_row.oid))
    order by r5k_catalog_proof.procedure_text(procedure_row.oid)),''[]''::jsonb)
    from pg_proc procedure_row join pg_language language on language.oid=procedure_row.prolang
    where procedure_row.oid in(
      to_regprocedure(''public.hotel_v2_partner_preview_seven_arches_pricing_proposal(jsonb)''),
      to_regprocedure(''public.hotel_v2_partner_submit_seven_arches_pricing_proposal(jsonb,uuid,uuid)''),
      to_regprocedure(''public.hotel_v2_admin_get_seven_arches_reviewed_pricing()''),
      to_regprocedure(''public.hotel_v2_admin_preview_seven_arches_reviewed_pricing(jsonb)''),
      to_regprocedure(''public.hotel_v2_admin_apply_seven_arches_reviewed_pricing(jsonb,uuid,uuid)''),
      to_regprocedure(''public.hotel_v2_7a_reviewed_pricing_partner_access_is_current(uuid)''),
      to_regprocedure(''public.hotel_v2_7a_reviewed_pricing_property_lineage_is_exact()''),
      to_regprocedure(''public.hotel_v2_7a_reviewed_pricing_plan_fingerprint(jsonb)''),
      to_regprocedure(''public.hotel_v2_seven_arches_reviewed_pricing_proposal_guard()''),
      to_regprocedure(''public.hotel_v2_seven_arches_reviewed_pricing_item_guard()''),
      to_regprocedure(''public.hotel_v2_seven_arches_reviewed_pricing_review_guard()''),
