 jsonb_build_array(r5k_catalog_proof.executor_bff8d2a3fa74580f9a97(to_jsonb(r5k_catalog_proof.executor_5b3fdcb3e5733f2ea8dd(p.oid))),r5k_catalog_proof.executor_b8213e04befe7b524baf(p.oid)) ORDER BY r5k_catalog_proof.procedure_text(p.oid))
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''hotel_stripe_connect_private''
 OR p.proname IN (''hotel_v2_stripe_connect_service'',''hotel_v2_admin_get_partner_stripe_onboarding_authorization'',
