 ''authorization_dependencies'',(SELECT jsonb_object_agg(r5k_catalog_proof.procedure_text(p.oid),
 jsonb_build_array(r5k_catalog_proof.executor_bff8d2a3fa74580f9a97(to_jsonb(r5k_catalog_proof.executor_5b3fdcb3e5733f2ea8dd(p.oid))),r5k_catalog_proof.executor_b8213e04befe7b524baf(p.oid)) ORDER BY r5k_catalog_proof.procedure_text(p.oid))
 FROM r5k_catalog_proof.historical_pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''hotel_stripe_connect_private''
 OR p.proname IN (''hotel_v2_stripe_connect_service'',''hotel_v2_admin_get_partner_stripe_onboarding_authorization'',
 ''hotel_v2_admin_set_partner_stripe_onboarding_authorization'',''hotel_v2_h2a_require_admin'',''is_current_user_admin'')),
 ''schema'',(SELECT jsonb_build_array(pg_get_userbyid(nspowner),nspacl) FROM pg_namespace WHERE nspname=''hotels_lifecycle_private''),
 ''functions'',(SELECT jsonb_object_agg(r5k_catalog_proof.procedure_text(p.oid),jsonb_build_object(''metadata'',r5k_catalog_proof.executor_b8213e04befe7b524baf(p.oid),
 ''hash'',r5k_catalog_proof.executor_bff8d2a3fa74580f9a97(to_jsonb(r5k_catalog_proof.executor_5b3fdcb3e5733f2ea8dd(p.oid)))) ORDER BY r5k_catalog_proof.procedure_text(p.oid))
 FROM r5k_catalog_proof.historical_pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''hotels_lifecycle_private''
 OR p.proname IN (''hotel_v2_admin_get_capability_lifecycle'',''hotel_v2_admin_set_capability_lifecycle'',''hotel_v2_attest_stripe_platform_readiness'')),
 ''relations'',(SELECT jsonb_agg(jsonb_build_object(''name'',c.relname,''owner'',pg_get_userbyid(c.relowner),''kind'',c.relkind,
 ''persistence'',c.relpersistence,''rls'',c.relrowsecurity,''force'',c.relforcerowsecurity,''acl'',c.relacl,
 ''columns'',(SELECT jsonb_agg(jsonb_build_array(a.attname,r5k_catalog_proof.type_text(a.atttypid),a.atttypmod,a.attnotnull,
 a.attidentity,a.attgenerated,r5k_catalog_proof.collation_text(a.attcollation),
 (SELECT r5k_catalog_proof.pg_get_expr(d.adbin,d.adrelid) FROM pg_attrdef d WHERE d.adrelid=a.attrelid AND d.adnum=a.attnum)) ORDER BY a.attnum)
 FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 ''constraints'',(SELECT jsonb_agg(jsonb_build_array(conname,convalidated,r5k_catalog_proof.pg_get_constraintdef(oid)) ORDER BY conname) FROM pg_constraint WHERE conrelid=c.oid),
 ''policies'',(SELECT jsonb_agg(to_jsonb(p)-''oid''-''polrelid'') FROM pg_policy p WHERE p.polrelid=c.oid),
 ''triggers'',(SELECT jsonb_agg(jsonb_build_array(t.tgname,t.tgenabled,r5k_catalog_proof.pg_get_triggerdef(t.oid)) ORDER BY t.tgname)
 FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) ORDER BY c.relname)
 FROM r5k_catalog_proof.historical_pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN (''hotels_lifecycle_private'',''hotel_stripe_connect_private'') AND c.relkind IN (''r'',''p'')),
 ''settings_guard'',(SELECT jsonb_build_array(t.tgenabled,r5k_catalog_proof.pg_get_triggerdef(t.oid)) FROM pg_trigger t
 WHERE t.tgrelid=''public.site_settings''::regclass AND t.tgname=''hotels_capability_lifecycle_guard'')) FROM dto_guard
';

CREATE OR REPLACE FUNCTION r5k_catalog_proof.executor_63e67309c0eb62b8fdb1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO pg_catalog, pg_temp
AS '
DECLARE f hotels_lifecycle_private.foundation%rowtype; d record; s jsonb; v bigint:=0; h text:=repeat(''0'',64); k text;
BEGIN
 SELECT * INTO STRICT f FROM hotels_lifecycle_private.foundation WHERE id=1;
 IF f.catalog IS DISTINCT FROM r5k_catalog_proof.executor_dfbc6217b32ff0fc9d47() THEN
  RAISE EXCEPTION ''hotels_lifecycle_catalog_drift''; END IF;
 s:=f.initial_flags||jsonb_build_object(''public_booking_enabled'',false);
 FOR d IN SELECT * FROM hotels_lifecycle_private.decisions ORDER BY version LOOP
  k:=CASE d.capability WHEN ''rooms'' THEN ''hotel_rooms_v2_enabled'' WHEN ''external'' THEN ''hotel_external_sync_enabled''
   WHEN ''stripe'' THEN ''hotel_stripe_connect_enabled'' WHEN ''instant'' THEN ''hotel_instant_booking_enabled''
   WHEN ''public_booking'' THEN ''public_booking_enabled'' END;
  IF k IS NULL OR d.version<>v+1 OR d.before_state IS DISTINCT FROM s
   OR d.after_state IS DISTINCT FROM jsonb_set(s,ARRAY[k],to_jsonb(d.enabled))
   OR d.after_state IS NOT DISTINCT FROM s OR d.previous_hash IS DISTINCT FROM h
   OR d.receipt_hash IS DISTINCT FROM r5k_catalog_proof.executor_bff8d2a3fa74580f9a97(
    (to_jsonb(d)-''receipt_hash''-''created_at'')||jsonb_build_object(''created_at_epoch'',extract(epoch FROM d.created_at)))
  THEN RAISE EXCEPTION ''hotels_lifecycle_chain_invalid''; END IF;
  s:=d.after_state; v:=d.version; h:=d.receipt_hash;
 END LOOP;
 IF (s->>''hotel_instant_booking_enabled'')::boolean OR (s->>''public_booking_enabled'')::boolean THEN
  RAISE EXCEPTION ''hotels_lifecycle_unsupported_public_stage''; END IF;
 RETURN jsonb_build_object(''version'',v,''state'',s,''receipt_hash'',h);
END ';

CREATE OR REPLACE FUNCTION r5k_catalog_proof.executor_bff8d2a3fa74580f9a97(p_value jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO pg_catalog, pg_temp
AS '
 SELECT encode(extensions.digest(convert_to(p_value::text,''UTF8''),''sha256''),''hex'')
';

CREATE OR REPLACE FUNCTION r5k_catalog_proof.executor_b8213e04befe7b524baf(p_oid oid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE STRICT SECURITY DEFINER
 SET search_path TO pg_catalog, pg_temp
AS '
 SELECT jsonb_build_object(''owner'',pg_get_userbyid(p.proowner),''language'',l.lanname,
 ''security_definer'',p.prosecdef,''volatility'',p.provolatile,''strict'',p.proisstrict,
 ''leakproof'',p.proleakproof,''returns_set'',p.proretset,''config'',p.proconfig,
 ''acl'',(SELECT jsonb_agg(jsonb_build_array(coalesce(r.rolname,''PUBLIC''),a.privilege_type,a.is_grantable)
 ORDER BY coalesce(r.rolname,''PUBLIC''),a.privilege_type,a.is_grantable)
 FROM aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner))) a LEFT JOIN pg_authid r ON r.oid=a.grantee))
 FROM r5k_catalog_proof.historical_pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=p_oid
';

CREATE OR REPLACE FUNCTION r5k_catalog_proof.executor_16ca30f652600d27d97d(p_oid oid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE STRICT SECURITY DEFINER
 SET search_path TO pg_catalog, pg_temp
AS '
DECLARE d text;
BEGIN
 PERFORM r5k_catalog_proof.executor_a863b682045432945008(p_oid);
 SELECT before_definition INTO d FROM hotels_lifecycle_private.bindings WHERE to_regprocedure(signature)=p_oid;
 RETURN coalesce(d,r5k_catalog_proof.executor_d9c50b44423349bd1d0e(p_oid));
END ';

CREATE OR REPLACE FUNCTION r5k_catalog_proof.executor_557f1a158b094e5dd5a0(p_flag text, p_actual boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO pg_catalog, pg_temp
AS '
DECLARE s jsonb;
BEGIN
 IF p_flag NOT IN (''hotel_rooms_v2_enabled'',''hotel_stripe_connect_enabled'') OR p_actual IS NULL THEN RETURN false; END IF;
 s:=r5k_catalog_proof.executor_9e863cbe183fb1f3d8e2();
 RETURN p_actual IS NOT DISTINCT FROM (s->''feature_flags''->>p_flag)::boolean;
END ';

CREATE OR REPLACE FUNCTION r5k_catalog_proof.executor_a863b682045432945008(p_oid oid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE STRICT SECURITY DEFINER
 SET search_path TO pg_catalog, pg_temp
AS '
DECLARE b hotels_lifecycle_private.bindings%rowtype; s text;
BEGIN
 SELECT r5k_catalog_proof.executor_5b3fdcb3e5733f2ea8dd(p_oid) INTO STRICT s;
 SELECT * INTO b FROM hotels_lifecycle_private.bindings WHERE to_regprocedure(signature)=p_oid;
 IF FOUND THEN
  IF encode(extensions.digest(convert_to(s,''UTF8''),''sha256''),''hex'') IS DISTINCT FROM b.after_hash
   OR r5k_catalog_proof.executor_b8213e04befe7b524baf(p_oid) IS DISTINCT FROM b.after_metadata
   OR encode(extensions.digest(convert_to(b.before_source,''UTF8''),''sha256''),''hex'') IS DISTINCT FROM b.before_hash
  THEN RAISE EXCEPTION ''hotels_lifecycle_evolved_source_security_drift''; END IF;
  RETURN b.before_source;
 END IF;
 RETURN s;
END ';

