      ''payment_policy_lineage'',encode(extensions.digest(convert_to((select r5k_catalog_proof.executor_a863b682045432945008(oid) from r5k_catalog_proof.historical_pg_proc where oid=
        ''public.hotel_v2_seven_arches_payment_policy_lineage_is_exact()''::regprocedure),
        ''UTF8''),''sha256''),''hex''),
      ''transaction_preservation'',encode(extensions.digest(convert_to((select r5k_catalog_proof.executor_a863b682045432945008(oid) from r5k_catalog_proof.historical_pg_proc where oid=
        ''public.hotel_v2_7a_pricing_activation_transaction_is_preserved()''::regprocedure),
        ''UTF8''),''sha256''),''hex''),
      ''promotion_inert_core'',encode(extensions.digest(convert_to((select r5k_catalog_proof.executor_a863b682045432945008(oid) from r5k_catalog_proof.historical_pg_proc where oid=
        ''public.hotel_v2_h3_1p_pricing_promotion_snapshot_inert_core(uuid)''::regprocedure),
        ''UTF8''),''sha256''),''hex''),
      ''promotion_snapshot'',encode(extensions.digest(convert_to((select r5k_catalog_proof.executor_a863b682045432945008(oid) from r5k_catalog_proof.historical_pg_proc where oid=
        ''public.hotel_v2_h3_1p_pricing_promotion_snapshot(uuid)''::regprocedure),
        ''UTF8''),''sha256''),''hex''),
      ''activation_state_validator'',encode(extensions.digest(convert_to((select r5k_catalog_proof.executor_a863b682045432945008(oid) from r5k_catalog_proof.historical_pg_proc where oid=
        ''public.hotel_v2_seven_arches_pricing_activation_state_is_exact()''::regprocedure),
        ''UTF8''),''sha256''),''hex''),
      ''parity_snapshot'',encode(extensions.digest(convert_to((select r5k_catalog_proof.executor_a863b682045432945008(oid) from r5k_catalog_proof.historical_pg_proc where oid=
        ''public.hotel_v2_h3_1p_parity_snapshot(uuid)''::regprocedure),
        ''UTF8''),''sha256''),''hex''),
      ''allocation_contract'',encode(extensions.digest(convert_to((select r5k_catalog_proof.executor_a863b682045432945008(oid) from r5k_catalog_proof.historical_pg_proc where oid=
        ''public.hotel_v2_admin_c_seven_kamares_allocation_contract_is_exact()''::regprocedure),
        ''UTF8''),''sha256''),''hex'')));
exception when no_data_found or too_many_rows then
