mation_schema.sql_identifier",-1,false,null],["table_schema","information_schema.sql_identifier",-1,false,null],["table_name","information_schema.sql_identifier",-1,false,null],["column_name","information_schema.sql_identifier",-1,false,null],["privilege_type","information_schema.character_data",-1,false,null],["is_grantable","information_schema.yes_or_no",-1,false,null]],"definition":" SELECT (u_grantor.rolname)::information_schema.sql_identifier AS grantor,\n    (grantee.rolname)::information_schema.sql_identifier AS grantee,\n    (current_database())::information_schema.sql_identifier AS table_catalog,\n    (nc.nspname)::information_schema.sql_identifier AS table_schema,\n    (x.relname)::information_schema.sql_identifier AS table_name,\n    (x.attname)::information_schema.sql_identifier AS column_name,\n    (x.prtype)::information_schema.character_data AS privilege_type,\n    (\n        CASE\n            WHEN (pg_has_role(x.grantee, x.relowner, ''USAGE''::text) OR x.grantable) THEN ''YES''::text\n            ELSE ''NO''::text\n        END)::information_schema.yes_or_no AS is_grantable\n   FROM ( SELECT pr_c.grantor,\n            pr_c.grantee,\n            a.attname,\n            pr_c.relname,\n            pr_c.relnamespace,\n            pr_c.prtype,\n            pr_c.grantable,\n            pr_c.relowner\n           FROM ( SELECT pg_class.oid,\n                    pg_class.relname,\n                    pg_class.relnamespace,\n                    pg_class.relowner,\n                    (aclexplode(COALESCE(pg_class.relacl, acldefault(''r''::\"char\", pg_class.relowner)))).grantor AS grantor,\n                    (aclexplode(COALESCE(pg_class.relacl, acldefault(''r''::\"char\", pg_class.relowner)))).grantee AS grantee,\n                    (aclexplode(COALESCE(pg_class.relacl, acldefault(''r''::\"char\", pg_class.relowner)))).privilege_type AS privilege_type,\n                    (aclexplode(COALESCE(pg_class.relacl, acldefault(''r''::\"char\", pg_class.relowner)))).is_grantable AS is_grantable\n                   FROM pg_class\n                  WHERE (pg_class.relkind = ANY (ARRAY[''r''::\"char\", ''v''::\"char\", ''f''::\"char\", ''p''::\"char\"]))) pr_c(oid, relname, relnamespace, relowner, grantor, grantee, prtype, grantable),\n            pg_attribute a\n          WHERE ((a.attrelid = pr_c.oid) AND (a.attnum > 0) AND (NOT a.attisdropped))\n        UNION\n         SELECT pr_a.grantor,\n            pr_a.grantee,\n            pr_a.attname,\n            c.relname,\n            c.relnamespace,\n            pr_a.prtype,\n            pr_a.grantable,\n            c.relowner\n           FROM ( SELECT a.attrelid,\n                    a.attname,\n                    (aclexplode(COALESCE(a.attacl, acldefault(''c''::\"char\", cc.relowner)))).grantor AS grantor,\n                    (aclexplode(COALESCE(a.attacl, acldefault(''c''::\"char\", cc.relowner)))).grantee AS grantee,\n                    (aclexplode(COALESCE(a.attacl, acldefault(''c''::\"char\", cc.relowner)))).privilege_type AS privilege_type,\n                    (aclexplode(COALESCE(a.attacl, acldefault(''c''::\"char\", cc.relowner)))).is_grantable AS is_grantable\n                   FROM (pg_attribute a\n                     JOIN pg_class cc ON ((a.attrelid = cc.oid)))\n                  WHERE ((a.attnum > 0) AND (NOT a.attisdropped))) pr_a(attrelid, attname, grantor, grantee, prtype, grantable),\n            pg_class c\n          WHERE ((pr_a.attrelid = c.oid) AND (c.relkind = ANY (ARRAY[''r''::\"char\", ''v''::\"char\", ''f''::\"char\", ''p''::\"char\"])))) x,\n    pg_namespace nc,\n    pg_authid u_grantor,\n    ( SELECT pg_authid.oid,\n            pg_authid.rolname\n           FROM pg_authid\n        UNION ALL\n         SELECT (0)::oid AS oid,\n            ''PUBLIC''::name) grantee(oid, rolname)\n  WHERE ((x.relnamespace = nc.oid) AND (x.grantee = grantee.oid) AND (x.grantor = u_grantor.oid) AND (x.prtype = ANY (ARRAY[''INSERT''::text, ''SELECT''::text, ''UPDATE''::text, ''REFERENCES''::text])) AND (pg_has_role(u_grantor.oid, ''USAGE''::text) OR pg_has_role(grantee.oid, ''USAGE''::text) OR (grantee.rolname = ''PUBLIC''::name)));","force_rls":false,"identity":"information_schema.column_privileges","kind":"v","options":null,"owner":"supabase_admin","rls":false},{"acl":[["supabase_admin","PUBLIC","SELECT",false],["supabase_admin","supabase_admin","DELETE",false],["supabase_admin","supabase_admin","INSERT",false],["supabase_admin","supabase_admin","MAINTAIN",false],["supabase_admin","supabase_admin","REFERENCES",false],["supabase_admin","supabase_admin","SELECT",false],["supabase_admin","supabase_admin","TRIGGER",false],["supabase_admin","supabase_admin","TRUNCATE",false],["supabase_admin","supabase_admin","UPDATE",false]],"columns":[["udt_catalog","information_schema.sql_identifier",-1,false,null],["udt_schema","information_schema.sql_identifier",-1,false,null],["udt_name","information_schema.sql_identifier",-1,false,null],["table_catalog","information_schema.sql_identifier",-1,false,null],["table_schema","information_schema.sql_identifier",-1,false,null],["table_name","information_schema.sql_identifier",-1,false,null],["column_name","information_schema.sql_identifier",-1,false,null]],"definition":" SELECT (current_database())::information_schema.sql_identifier AS udt_catalog,\n    (COALESCE(nbt.nspname, nt.nspname))::information_schema.sql_identifier AS udt_schema,\n    (COALESCE(bt.typname, t.typname))::information_schema.sql_identifier AS udt_name,\n    (current_database())::information_schema.sql_identifier AS table_catalog,\n    (nc.nspname)::information_schema.sql_identifier AS table_schema,\n    (c.relname)::information_schema.sql_identifier AS table_name,\n    (a.attname)::information_schema.sql_identifier AS column_name\n   FROM pg_attribute a,\n    pg_class c,\n    pg_namespace nc,\n    ((pg_type t\n     JOIN pg_namespace nt ON ((t.typnamespace = nt.oid)))\n     LEFT JOIN (pg_type bt\n     JOIN pg_namespace nbt ON ((bt.typnamespace = nbt.oid))) ON (((t.typtype = ''d''::\"char\") AND (t.typbasetype = bt.oid))))\n  WHERE ((a.attrelid = c.oid) AND (a.atttypid = t.oid) AND (nc.oid = c.relnamespace) AND (a.attnum > 0) AND (NOT a.attisdropped) AND (c.relkind = ANY (ARRAY[''r''::\"char\", ''v''::\"char\", ''f''::\"char\", ''p''::\"char\"])) AND pg_has_role(COALESCE(bt.typowner, t.typowner), ''USAGE''::text));","force_rls":false,"identity":"information_schema.column_udt_usage","kind":"v","options":null,"owner":"supabase_admin","rls":false},{"acl":[["supabase_admin","PUBLIC","SELECT",false],["supabase_admin","supabase_admin","DELETE",false],["supabase_admin","supabase_admin","INSERT",false],["supabase_admin","supabase_admin","MAINTAIN",false],["supabase_admin","supabase_admin","REFERENCES",false],["supabase_admin","supabase_admin","SELECT",false],["supabase_admin","supabase_admin","TRIGGER",false],["supabase_admin","supabase_admin","TRUNCATE",false],["supabase_admin","supabase_admin","UPDATE",false]],"columns":[["table_catalog","information_schema.sql_identifier",-1,false,null],["table_schema","information_schema.sql_identifier",-1,false,null],["table_name","information_schema.sql_identifier",-1,false,null],["column_name","information_schema.sql_identifier",-1,false,null],["ordinal_position","information_schema.cardinal_number",-1,false,null],["column_default","information_schema.character_data",-1,false,null],["is_nullable","information_schema.yes_or_no",-1,false,null],["data_type","information_schema.character_data",-1,false,null],["character_maximum_length","information_schema.cardinal_number",-1,false,null],["character_octet_length","information_schema.cardinal_number",-1,false,null],["numeric_precision","information_schema.cardinal_number",-1,false,null],["numeric_precision_radix","information_schema.cardinal_number",-1,false,null],["numeric_scale","information_schema.cardinal_number",-1,false,null],["datetime_precision","information_schema.cardinal_number",-1,false,null],["interval_ty