GGER",false],["supabase_admin","supabase_admin","TRUNCATE",false],["supabase_admin","supabase_admin","UPDATE",false]],"columns":[["constraint_catalog","information_schema.sql_identifier",-1,false,null],["constraint_schema","information_schema.sql_identifier",-1,false,null],["constraint_name","information_schema.sql_identifier",-1,false,null],["domain_catalog","information_schema.sql_identifier",-1,false,null],["domain_schema","information_schema.sql_identifier",-1,false,null],["domain_name","information_schema.sql_identifier",-1,false,null],["is_deferrable","information_schema.yes_or_no",-1,false,null],["initially_deferred","information_schema.yes_or_no",-1,false,null]],"definition":" SELECT (current_database())::information_schema.sql_identifier AS constraint_catalog,\n    (rs.nspname)::information_schema.sql_identifier AS constraint_schema,\n    (con.conname)::information_schema.sql_identifier AS constraint_name,\n    (current_database())::information_schema.sql_identifier AS domain_catalog,\n    (n.nspname)::information_schema.sql_identifier AS domain_schema,\n    (t.typname)::information_schema.sql_identifier AS domain_name,\n    (\n        CASE\n            WHEN con.condeferrable THEN ''YES''::text\n            ELSE ''NO''::text\n        END)::information_schema.yes_or_no AS is_deferrable,\n    (\n        CASE\n            WHEN con.condeferred THEN ''YES''::text\n            ELSE ''NO''::text\n        END)::information_schema.yes_or_no AS initially_deferred\n   FROM pg_namespace rs,\n    pg_namespace n,\n    pg_constraint con,\n    pg_type t\n  WHERE ((rs.oid = con.connamespace) AND (n.oid = t.typnamespace) AND (t.oid = con.contypid) AND (pg_has_role(t.typowner, ''USAGE''::text) OR has_type_privilege(t.oid, ''USAGE''::text)));","force_rls":false,"identity":"information_schema.domain_constraints","kind":"v","options":null,"owner":"supabase_admin","rls":false},{"acl":[["supabase_admin","PUBLIC","SELECT",false],["supabase_admin","supabase_admin","DELETE",false],["supabase_admin","supabase_admin","INSERT",false],["supabase_admin","supabase_admin","MAINTAIN",false],["supabase_admin","supabase_admin","REFERENCES",false],["supabase_admin","supabase_admin","SELECT",false],["supabase_admin","supabase_admin","TRIGGER",false],["supabase_admin","supabase_admin","TRUNCATE",false],["supabase_admin","supabase_admin","UPDATE",false]],"columns":[["udt_catalog","information_schema.sql_identifier",-1,false,null],["udt_schema","information_schema.sql_identifier",-1,false,null],["udt_name","information_schema.sql_identifier",-1,false,null],["domain_catalog","information_schema.sql_identifier",-1,false,null],["domain_schema","information_schema.sql_identifier",-1,false,null],["domain_name","information_schema.sql_identifier",-1,false,null]],"definition":" SELECT (current_database())::information_schema.sql_identifier AS udt_catalog,\n    (nbt.nspname)::information_schema.sql_identifier AS udt_schema,\n    (bt.typname)::information_schema.sql_identifier AS udt_name,\n    (current_database())::information_schema.sql_identifier AS domain_catalog,\n    (nt.nspname)::information_schema.sql_identifier AS domain_schema,\n    (t.typname)::information_schema.sql_identifier AS domain_name\n   FROM pg_type t,\n    pg_namespace nt,\n    pg_type bt,\n    pg_namespace nbt\n  WHERE ((t.typnamespace = nt.oid) AND (t.typbasetype = bt.oid) AND (bt.typnamespace = nbt.oid) AND (t.typtype = ''d''::\"char\") AND pg_has_role(bt.typowner, ''USAGE''::text));","force_rls":false,"identity":"information_schema.domain_udt_usage","kind":"v","options":null,"owner":"supabase_admin","rls":false},{"acl":[["supabase_admin","PUBLIC","SELECT",false],["supabase_admin","supabase_admin","DELETE",false],["supabase_admin","supabase_admin","INSERT",false],["supabase_admin","supabase_admin","MAINTAIN",false],["supabase_admin","supabase_admin","REFERENCES",false],["supabase_admin","supabase_admin","SELECT",false],["supabase_admin","supabase_admin","TRIGGER",false],["supabase_admin","supa