definition":" SELECT (current_database())::information_schema.sql_identifier AS domain_catalog,\n    (nt.nspname)::information_schema.sql_identifier AS domain_schema,\n    (t.typname)::information_schema.sql_identifier AS domain_name,\n    (\n        CASE\n            WHEN ((t.typelem <> (0)::oid) AND (t.typlen = ''-1''::integer)) THEN ''ARRAY''::text\n            WHEN (nbt.nspname = ''pg_catalog''::name) THEN format_type(t.typbasetype, NULL::integer)\n            ELSE ''USER-DEFINED''::text\n        END)::information_schema.character_data AS data_type,\n    (information_schema._pg_char_max_length(t.typbasetype, t.typtypmod))::information_schema.cardinal_number AS character_maximum_length,\n    (information_schema._pg_char_octet_length(t.typbasetype, t.typtypmod))::information_schema.cardinal_number AS character_octet_length,\n    (NULL::name)::information_schema.sql_identifier AS character_set_catalog,\n    (NULL::name)::information_schema.sql_identifier AS character_set_schema,\n    (NULL::name)::information_schema.sql_identifier AS character_set_name,\n    (\n        CASE\n            WHEN (nco.nspname IS NOT NULL) THEN current_database()\n            ELSE NULL::name\n        END)::information_schema.sql_identifier AS collation_catalog,\n    (nco.nspname)::information_schema.sql_identifier AS collation_schema,\n    (co.collname)::information_schema.sql_identifier AS collation_name,\n    (information_schema._pg_numeric_precision(t.typbasetype, t.typtypmod))::information_schema.cardinal_number AS numeric_precision,\n    (information_schema._pg_numeric_precision_radix(t.typbasetype, t.typtypmod))::information_schema.cardinal_number AS numeric_precision_radix,\n    (information_schema._pg_numeric_scale(t.typbasetype, t.typtypmod))::information_schema.cardinal_number AS numeric_scale,\n    (information_schema._pg_datetime_precision(t.typbasetype, t.typtypmod))::information_schema.cardinal_number AS datetime_precision,\n    (information_schema._pg_interval_type(t.typbasetype, t.typtypmod))::information_schema.character_data AS interval_type,\n    (NULL::integer)::information_schema.cardinal_number AS interval_precision,\n    (t.typdefault)::information_schema.character_data AS domain_default,\n    (current_database())::information_schema.sql_identifier AS udt_catalog,\n    (nbt.nspname)::information_schema.sql_identifier AS udt_schema,\n    (bt.typname)::information_schema.sql_identifier AS udt_name,\n    (NULL::name)::information_schema.sql_identifier AS scope_catalog,\n    (NULL::name)::information_schema.sql_identifier AS scope_schema,\n    (NULL::name)::information_schema.sql_identifier AS scope_name,\n    (NULL::integer)::information_schema.cardinal_number AS maximum_cardinality,\n    (1)::information_schema.sql_identifier AS dtd_identifier\n   FROM (((pg_type t\n     JOIN pg_namespace nt ON ((t.typnamespace = nt.oid)))\n     JOIN (pg_type bt\n     JOIN pg_namespace nbt ON ((bt.typnamespace = nbt.oid))) ON (((t.typbasetype = bt.oid) AND (t.typtype = ''d''::\"char\"))))\n     LEFT JOIN (pg_collation co\n     JOIN pg_namespace nco ON ((co.collnamespace = nco.oid))) ON (((t.typcollation = co.oid) AND ((nco.nspname <> ''pg_catalog''::name) OR (co.collname <> ''default''::name)))))\n  WHERE (pg_has_role(t.typowner, ''USAGE''::text) OR has_type_privilege(t.oid, ''USAGE''::text));","force_rls":false,"identity":"information_schema.domains","kind":"v","options":null,"owner":"supabase_admin","rls":false},{"acl":[["supabase_admin","PUBLIC","SELECT",false],["supabase_admin","supabase_admin","DELETE",false],["supabase_admin","supabase_admin","INSERT",false],["supabase_admin","supabase_admin","MAINTAIN",false],["supabase_admin","supabase_admin","REFERENCES",false],["supabase_admin","supabase_admin","SELECT",false],["supabase_admin","supabase_admin","TRIGGER",false],["supabase_admin","supabase_admin","TRUNCATE",false],["supabase_admin","supabase_admin","UPDATE",false]],"columns":[["object_catalog","information_schema.sql_identifier",-1,false,null],["object_schema","information_schema.sql_identifier",-1,false,null],["object_name","information_schema.sql_identifier",-1,false,null],["object_type","information_schema.character_data",-1,false,null],["collection_type_identifier","information_schema.sql_identifier",-1,false,null],["data_type","information_schema.character_data",-1,false,null],["character_maximum_length","information_schema.cardinal_number",-1,false,null],["character_octet_length","information_schema.cardinal_number",-1,false,null],["character_set_catalog","information_schema.sql_identifier",-1,false,null],["character_set_schema","information_schema.sql_identifier",-1,false,null],["character_set_name","information_schema.sql_identifier",-1,false,null],["collation_catalog","information_schema.sql_identifier",-1,false,null],["collation_schema","information_schema.sql_identifier",-1,false,null],["collation_name","information_schema.sql_identifier",-1,false,null],["numeric_precision","information_schema.cardinal_number",-1,false,null],["numeric_precision_radix","information_schema.cardinal_number",-1,false,null],["numeric_scale","information_schema.cardinal_number",-1,false,null],["datetime_precision","information_schema.cardinal_number",-1,false,null],["interval_type","information_schema.character_data",-1,false,null],["interval_precision","information_schema.cardinal_number",-1,false,null],["udt_catalog","information_schema.sql_identifier",-1,false,null],["udt_schema","information_schema.sql_identifier",-1,false,null],["udt_name","information_schema.sql_identifier",-1,false,null],["scope_catalog","information_schema.sql_identifier",-1,false,null],["scope_schema","information_schema.sql_identifier",-1,false,null],["scope_name","information_schema.sql_identifier",-1,false,null],["maximum_cardinality","information_schema.cardinal_number",-1,false,null],["dtd_identifier","information_schema.sql_identifier",-1,false,null]],"definition":" SELECT (current_database())::information_schema.sql_identifie