) THEN (stat.a).stavalues3\n            WHEN ((stat.a).stakind4 = 2) THEN (stat.a).stavalues4\n            WHEN ((stat.a).stakind5 = 2) THEN (stat.a).stavalues5\n            ELSE NULL::anyarray\n        END AS histogram_bounds,\n        CASE\n            WHEN ((stat.a).stakind1 = 3) THEN (stat.a).stanumbers1[1]\n            WHEN ((stat.a).stakind2 = 3) THEN (stat.a).stanumbers2[1]\n            WHEN ((stat.a).stakind3 = 3) THEN (stat.a).stanumbers3[1]\n            WHEN ((stat.a).stakind4 = 3) THEN (stat.a).stanumbers4[1]\n            WHEN ((stat.a).stakind5 = 3) THEN (stat.a).stanumbers5[1]\n            ELSE NULL::real\n        END AS correlation,\n        CASE\n            WHEN ((stat.a).stakind1 = 4) THEN (stat.a).stavalues1\n            WHEN ((stat.a).stakind2 = 4) THEN (stat.a).stavalues2\n            WHEN ((stat.a).stakind3 = 4) THEN (stat.a).stavalues3\n            WHEN ((stat.a).stakind4 = 4) THEN (stat.a).stavalues4\n            WHEN ((stat.a).stakind5 = 4) THEN (stat.a).stavalues5\n            ELSE NULL::anyarray\n        END AS most_common_elems,\n        CASE\n            WHEN ((stat.a).stakind1 = 4) THEN (stat.a).stanumbers1\n            WHEN ((stat.a).stakind2 = 4) THEN (stat.a).stanumbers2\n            WHEN ((stat.a).stakind3 = 4) THEN (stat.a).stanumbers3\n            WHEN ((stat.a).stakind4 = 4) THEN (stat.a).stanumbers4\n            WHEN ((stat.a).stakind5 = 4) THEN (stat.a).stanumbers5\n            ELSE NULL::real[]\n        END AS most_common_elem_freqs,\n        CASE\n            WHEN ((stat.a).stakind1 = 5) THEN (stat.a).stanumbers1\n            WHEN ((stat.a).stakind2 = 5) THEN (stat.a).stanumbers2\n            WHEN ((stat.a).stakind3 = 5) THEN (stat.a).stanumbers3\n            WHEN ((stat.a).stakind4 = 5) THEN (stat.a).stanumbers4\n            WHEN ((stat.a).stakind5 = 5) THEN (stat.a).stanumbers5\n            ELSE NULL::real[]\n        END AS elem_count_histogram\n   FROM (((((pg_statistic_ext s\n     JOIN pg_class c ON ((c.oid = s.stxrelid)))\n     LEFT JOIN pg_statistic_ext_data sd ON ((s.oid = sd.stxoid)))\n     LEFT JOIN pg_namespace cn ON ((cn.oid = c.relnamespace)))\n     LEFT JOIN pg_namespace sn ON ((sn.oid = s.stxnamespace)))\n     JOIN LATERAL ( SELECT unnest(pg_get_statisticsobjdef_expressions(s.oid)) AS expr,\n            unnest(sd.stxdexpr) AS a) stat ON ((stat.expr IS NOT NULL)))\n  WHERE (pg_has_role(c.relowner, ''USAGE''::text) AND ((c.relrowsecurity = false) OR (NOT row_security_active(c.oid))));","force_rls":false,"identity":"pg_catalog.pg_stats_ext_exprs","kind":"v","options":["security_barrier=true"],"owner":"supabase_admin","rls":false},{"acl":[["supabase_admin","PUBLIC","SELECT",false],["supabase_admin","supabase_admin","DELETE",false],["supabase_admin","supabase_admin","INSERT",false],["supabase_admin","supabase_admin","MAINTAIN",false],["supabase_admin","supabase_admin","REFERENCES",false],["supabase_admin","supabase_admin","SELECT",false],["supabase_admin","supabase_admin","TRIGGER",false],["supabase_admin","supabase_admin","TRUNCATE",false],["supabase_admin","supabase_admin","UPDATE",false]],"columns":[["schemaname","pg_catalog.name",-1,false,null],["tablename","pg_catalog.name",-1,false,null],["tableowner","pg_catalog.name",-1,false,null],["tablespace","pg_catalog.name",-1,false,null],["hasindexes","pg_catalog.bool",-1,false,null],["hasrules","pg_catalog.bool",-1,false,null],["hastriggers","pg_catalog.bool",-1,false,null],["rowsecurity","pg_catalog.bool",-1,false,null]],"definition":" SELECT n.nspname AS schemaname,\n    c.relname AS tablename,\n    pg_get_userbyid(c.relowner) AS tableowner,\n    t.spcname AS tablespace,\n    c.relhasindex AS hasindexes,\n    c.relhasrules AS hasrules,\n    c.relhastriggers AS hastriggers,\n    c.relrowsecurity AS rowsecurity\n   FROM ((pg_class c\n     LEFT JOIN pg_namespace n ON ((n.oid = c.relnamespace)))\n     LEFT JOIN pg_tablespace t ON ((t.oid = c.reltablespace)))\n  WHERE (c.relkind = ANY (ARRAY[''r''::\"char\", ''p''::\"char\"]));","fo