N (u.umuser = (0)::oid) THEN ''public''::name\n            ELSE a.rolname\n        END AS usename,\n        CASE\n            WHEN (((u.umuser <> (0)::oid) AND (a.rolname = CURRENT_USER) AND (pg_has_role(s.srvowner, ''USAGE''::text) OR has_server_privilege(s.oid, ''USAGE''::text))) OR ((u.umuser = (0)::oid) AND pg_has_role(s.srvowner, ''USAGE''::text)) OR ( SELECT pg_authid.rolsuper\n               FROM pg_authid\n              WHERE (pg_authid.rolname = CURRENT_USER))) THEN u.umoptions\n            ELSE NULL::text[]\n        END AS umoptions\n   FROM ((pg_user_mapping u\n     JOIN pg_foreign_server s ON ((u.umserver = s.oid)))\n     LEFT JOIN pg_authid a ON ((a.oid = u.umuser)));","force_rls":false,"identity":"pg_catalog.pg_user_mappings","kind":"v","options":null,"owner":"supabase_admin","rls":false},{"acl":[["supabase_admin","PUBLIC","SELECT",false],["supabase_admin","supabase_admin","DELETE",false],["supabase_admin","supabase_admin","INSERT",false],["supabase_admin","supabase_admin","MAINTAIN",false],["supabase_admin","supabase_admin","REFERENCES",false],["supabase_admin","supabase_admin","SELECT",false],["supabase_admin","supabase_admin","TRIGGER",false],["supabase_admin","supabase_admin","TRUNCATE",false],["supabase_admin","supabase_admin","UPDATE",false]],"columns":[["schemaname","pg_catalog.name",-1,false,null],["viewname","pg_catalog.name",-1,false,null],["viewowner","pg_catalog.name",-1,false,null],["definition","pg_catalog.text",-1,false,null]],"definition":" SELECT n.nspname AS schemaname,\n    c.relname AS viewname,\n    pg_get_userbyid(c.relowner) AS viewowner,\n    pg_get_viewdef(c.oid) AS definition\n   FROM (pg_class c\n     LEFT JOIN pg_namespace n ON ((n.oid = c.relnamespace)))\n  WHERE (c.relkind = ''v''::\"char\");","force_rls":false,"identity":"pg_catalog.pg_views","kind":"v","options":null,"owner":"supabase_admin","rls":false},{"acl":[["supabase_admin","PUBLIC","SELECT",false],["supabase_admin","supabase_admin","DELETE",false],["supabase_admin