(a.atttypmod)), ''GEOMETRY''::text), st.type, ''GEOMETRY''::text), ''ZM''::text, ''''::text), ''Z''::text, ''''::text))::character varying(30) AS type\n   FROM ((((((pg_class c\n     JOIN pg_attribute a ON (((a.attrelid = c.oid) AND (NOT a.attisdropped))))\n     JOIN pg_namespace n ON ((c.relnamespace = n.oid)))\n     JOIN pg_type t ON ((a.atttypid = t.oid)))\n     LEFT JOIN ( SELECT s.connamespace,\n            s.conrelid,\n            s.conkey,\n            replace(split_part(s.consrc, ''''''''::text, 2), '')''::text, ''''::text) AS type\n           FROM ( SELECT pg_constraint.connamespace,\n                    pg_constraint.conrelid,\n                    pg_constraint.conkey,\n                    pg_get_constraintdef(pg_constraint.oid) AS consrc\n                   FROM pg_constraint) s\n          WHERE (s.consrc ~~* ''%geometrytype(% = %''::text)) st ON (((st.connamespace = n.oid) AND (st.conrelid = c.oid) AND (a.attnum = ANY (st.conkey)))))\n     LEFT JOIN ( SELECT s.connamespace,\n            s.conrelid,\n            s.conkey,\n            (replace(split_part(s.consrc, '' = ''::text, 2), '')''::text, ''''::text))::integer AS ndims\n           FROM ( SELECT pg_constraint.connamespace,\n                    pg_constraint.conrelid,\n                    pg_constraint.conkey,\n                    pg_get_constraintdef(pg_constraint.oid) AS consrc\n                   FROM pg_constraint) s\n          WHERE (s.consrc ~~* ''%ndims(% = %''::text)) sn ON (((sn.connamespace = n.oid) AND (sn.conrelid = c.oid) AND (a.attnum = ANY (sn.conkey)))))\n     LEFT JOIN ( SELECT s.connamespace,\n            s.conrelid,\n            s.conkey,\n            (replace(replace(split_part(s.consrc, '' = ''::text, 2), '')''::text, ''''::text), ''(''::text, ''''::text))::integer AS srid\n           FROM ( SELECT pg_constraint.connamespace,\n                    pg_constraint.conrelid,\n                    pg_constraint.conkey,\n                    pg_get_constraintdef(pg_constraint.oid) AS consrc\n                   FROM pg_constraint) s\n          WHERE (s.consrc ~~* ''%srid(% = %''::text)) sr ON (((sr.connamespace = n.oid) AND (sr.conrelid = c.oid) AND (a.attnum = ANY (sr.conkey)))))\n  WHERE ((c.relkind = ANY (ARRAY[''r''::\"char\", ''v''::\"char\", ''m''::\"char\", ''f''::\"char\", ''p''::\"char\"])) AND (NOT (c.relname = ''raster_columns''::name)) AND (t.typname = ''geometry''::name) AND (NOT pg_is_other_temp_schema(c.relnamespace)) AND has_table_privilege(c.oid, ''SELECT''::text));","force_rls":false,"identity":"public.geometry_columns","kind":"v","options":null,"owner":"supabase_admin","rls":false},{"acl":[["postgres","anon","SELECT",false],["postgres","authenticated","SELECT",false],["postgres","postgres","DELETE",false],["postgres","postgres","INSERT",false],["postgres","postgres","MAINTAIN",false],["postgres","postgres","REFERENCES",false],["postgres","postgres","SELECT",false],["postgres","postgres","TRIGGER",false],["postgres","postgres","TRUNCATE",false],["postgres","postgres","UPDATE",false],["postgres","service_role","DELETE",false],["postgres","service_role","INSERT",false],["postgres","service_role","MAINTAIN",false],["postgres","service_role","REFERENCES",false],["postgres","service_role","SELECT",false],["postgres","service_role","TRIGGER",false],["postgres","service_role","TRUNCATE",false],["postgres","service_role","UPDATE",false]],"columns":[["poi_id","pg_catalog.text",-1,false,null],["total_ratings","pg_catalog.int8",-1,false,null],["average_rating","pg_catalog.numeric",-1,false,null],["five_star","pg_catalog.int8",-1,false,null],["four_star","pg_catalog.int8",-1,false,null],["three_star","pg_catalog.int8",-1,false,null],["two_star","pg_catalog.int8",-1,false,null],["one_star","pg_catalog.int8",-1,false,null],["last_rated_at","pg_catalog.timestamptz",-1,false,null]],"definition":" SELECT poi_id,\n    count(*) AS total_ratings,\n    round(avg(rating), 2) AS average_rating,\n    count(\n        CASE\n            WHEN (rating = 5) THEN