 FOR i IN 0..31 LOOP
  inner_pad:=set_byte(inner_pad,i,get_byte(inner_pad,i)#get_byte(k,i));
  outer_pad:=set_byte(outer_pad,i,get_byte(outer_pad,i)#get_byte(k,i));
