CREATE FUNCTION hotels_published_architecture_private.foundation_f46b02a57427361e() RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER   SET search_path TO 'pg_catalog', 'pg_temp'  SET timezone TO 'UTC' AS '
declare c_source constant uuid:=''b0a3104f-7b31-5265-a59f-c2d166f11a23'';
  v_phase1 public.hotel_seven_arches_independent_pricing_evolution_receipts%rowtype;
