 (id='9b6d99a0-923a-4fbc-be54-c066e856e6ca' AND architecture_version='rooms_v2' AND is_published=true));

CREATE FUNCTION hotels_published_architecture_private.business_snapshot() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS 'SELECT pg_catalog.jsonb_object_agg(relation,value ORDER BY relation COLLATE "C") FROM (VALUES (''hotel_stripe_connect_private.accounts'',(SELECT COALESCE(pg_catalog.jsonb_agg(v ORDER BY v::text COLLATE "C"),''[]''::pg_catalog.jsonb) AS value FROM (SELECT (SELECT pg_catalog.to_jsonb(projected) FROM (SELECT t."partner_id",t."account_id",t."live_mode",t."status",t."revoked",t."revision",t."checked_at") projected) AS v FROM hotel_stripe_connect_private.accounts t WHERE t.partner_id=''0a321bfe-da6b-43f6-8e0b-7c68546a8b18''::pg_catalog.uuid) selected)),
(''hotels_lifecycle_private.bindings'',(SELECT COALESCE(pg_catalog.jsonb_agg(v ORDER BY v::text COLLATE "C"),''[]''::pg_catalog.jsonb) AS value FROM (SELECT (SELECT pg_catalog.to_jsonb(projected) FROM (SELECT t."signature",t."before_source",t."before_definition",t."before_hash",t."after_hash",t."after_metadata") projected) AS v FROM hotels_lifecycle_private.bindings t WHERE TRUE) selected)),
(''hotels_lifecycle_private.decisions'',(SELECT COALESCE(pg_catalog.jsonb_agg(v ORDER BY v::text COLLATE "C"),''[]''::pg_catalog.jsonb) AS value FROM (SELECT (SELECT pg_catalog.to_jsonb(projected) FROM (SELECT t."version",t."request_id",t."actor_id",t."capability",t."enabled",t."reason",t."before_state",t."after_state",t."previous_hash",t."receipt_hash",t."created_at") projected) AS v FROM hotels_lifecycle_private.decisions t WHERE TRUE) selected)),
(''hotels_lifecycle_private.foundation'',(SELECT COALESCE(pg_catalog.jsonb_agg(v ORDER BY v::text COLLATE "C"),''[]''::pg_catalog.jsonb) AS value FROM (SELECT (SELECT pg_catalog.to_jsonb(projected) FROM (SELECT t."id",t."initial_flags",t."catalog",t."predecessor_receipts") projected) AS v FROM hotels_lifecycle_private.foundation t WHERE TRUE) selected)),
(''hotels_lineage_private.reconciliation_receipts'',(SELECT COALESCE(pg_catalog.jsonb_agg(v ORDER BY v::text COLLATE "C"),''[]''::pg_catalog.jsonb) AS value FROM (SELECT (SELECT pg_catalog.to_jsonb(projected) FROM (SELECT t."id",t."contract_version",t."evidence",t."evidence_hash",t."created_at") projected) AS v FROM hotels_lineage_private.reconciliation_receipts t WHERE TRUE) selected)),
(''hotels_lineage_private.successor_receipts'',(SELECT COALESCE(pg_catalog.jsonb_agg(v ORDER BY v::text COLLATE "C"),''[]''::pg_catalog.jsonb) AS value FROM (SELECT (SELECT pg_catalog.to_jsonb(projected) FROM (SELECT t."stage",t."previous_hash",t."bindings",t."receipt_hash") projected) AS v FROM hotels_lineage_private.successor_receipts t WHERE TRUE) selected)),
