''policies'',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(p.polname,p.polcmd,p.polpermissive,(SELECT pg_catalog.jsonb_agg(CASE WHEN u=0 THEN ''PUBLIC'' ELSE pg_catalog.pg_get_userbyid(u) END ORDER BY u) FROM pg_catalog.unnest(p.polroles) u),pg_catalog.pg_get_expr(p.polqual,p.polrelid),pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY p.polname) FROM pg_catalog.pg_policy p WHERE p.polrelid=r.oid)
