';

CREATE FUNCTION hotels_published_architecture_private.assert_exact() RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $cert$
DECLARE c hotels_published_architecture_private.foundation_certificate%rowtype;
BEGIN
 SELECT * INTO STRICT c FROM hotels_published_architecture_private.foundation_certificate WHERE id=1;
 IF (SELECT count(*) FROM hotels_published_architecture_private.foundation_certificate)<>1 OR c.entrypoints->>'epoch'<>'2'
 OR c.entrypoints->>'before_hash' IS DISTINCT FROM hotels_published_architecture_private.digest(c.predecessors)
 OR c.entrypoints->>'after_hash' IS DISTINCT FROM hotels_published_architecture_private.digest(c.helpers)
 OR c.entrypoints->>'transformation_hash' IS DISTINCT FROM hotels_published_architecture_private.digest(c.relation_catalog)
 OR NOT r5k_catalog_proof.payment_catalog_is_exact()
 OR c.relation_catalog->'payment_catalog' IS DISTINCT FROM r5k_catalog_proof.payment_catalog()
 OR c.helpers IS DISTINCT FROM hotels_published_architecture_private.actual_catalog() THEN RAISE EXCEPTION 'hotels_114489_v2_catalog_epoch_drift'; END IF;
END $cert$;

CREATE FUNCTION hotels_published_architecture_private.snapshot_v2() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $snapshot$
DECLARE s jsonb; a jsonb; catalog_hash text;
BEGIN
 IF (SELECT count(*) FROM public.hotel_seven_arches_pricing_activation_evolution_receipts)<>1 OR (SELECT count(*) FROM public.hotel_seven_arches_task2_stage2_compatibility_receipts)<>1 OR (SELECT count(*) FROM public.hotel_seven_arches_reviewed_pricing_foundation_receipts)<>1 THEN RAISE EXCEPTION 'hotels_114489_v2_historical_bootstrap_rejected'; END IF;
 s:=hotels_published_architecture_private.state_snapshot();
 a:=pg_catalog.jsonb_build_object('actor_id',auth.uid(),'admin',r5k_catalog_proof.executor_f3c9e058e8d04f22d3c5());
 SELECT entrypoints->>'after_hash' INTO STRICT catalog_hash FROM hotels_published_architecture_private.foundation_certificate WHERE id=1;
 RETURN s||pg_catalog.jsonb_build_object('snapshot_version','hotels_v2_published_conversion_snapshot_v2','catalog_epoch',2,'static_catalog_hash',catalog_hash,'authorization',a);
END $snapshot$;

CREATE FUNCTION public.hotel_v2_admin_get_published_architecture_conversion_114489(p_hotel_id uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $plan$
DECLARE s jsonb; p jsonb; actor uuid; request uuid; issued timestamptz;
BEGIN
 PERFORM hotels_published_architecture_private.acquire_v2_locks(); PERFORM hotels_published_architecture_private.assert_exact(); PERFORM r5k_catalog_proof.executor_db9a78732b40d447eaa2();
 actor:=auth.uid();
 IF actor IS NULL OR p_hotel_id IS DISTINCT FROM '9b6d99a0-923a-4fbc-be54-c066e856e6ca'::uuid THEN RAISE EXCEPTION 'hotels_114489_target_required'; END IF;
 s:=hotels_published_architecture_private.snapshot_v2(); request:=pg_catalog.gen_random_uuid(); issued:=pg_catalog.clock_timestamp();
 IF s#>>'{hotel,architecture_version}'='rooms_v2' THEN RETURN pg_catalog.jsonb_build_object('contract_version','hotels_v2_published_conversion_readiness_v2','status','ALREADY_CONVERTED','hotel_id',p_hotel_id,'plan',NULL); END IF;
 p:=pg_catalog.jsonb_build_object('contract_version','hotels_v2_published_conversion_plan_v2','snapshot_version','hotels_v2_published_conversion_snapshot_v2','catalog_epoch',2,
 'static_catalog_hash',s->'static_catalog_hash','actor_id',actor,'hotel_id',p_hotel_id,'partner_id','0a321bfe-da6b-43f6-8e0b-7c68546a8b18','assignment_id','a082c085-a6ea-46fd-8548-c8d9c6ee2c34',
 'request_id',request,'issued_at',issued,'expires_at',issued+interval '15 minutes','from','legacy','to','rooms_v2','is_published',true,'public_booking_enabled',false,
 'authorization',s->'authorization','authorization_hash',hotels_published_architecture_private.digest(s->'authorization'),'snapshot_hash',hotels_published_architecture_private.digest(s),
 'business_state_hash',hotels_published_architecture_private.digest(s->'business'),'lifecycle_hash',hotels_published_architecture_private.digest(s->'lifecycle'),'lineage_hash',hotels_published_architecture_private.digest(s->'pricing'),
 'commission_payment_hash',hotels_published_architecture_private.digest(pg_catalog.jsonb_build_array(s#>'{pricing,commission_fingerprint}',s#>'{pricing,payment_fingerprint}')),'pricing_allocation_hash',hotels_published_architecture_private.digest(s->'pricing'));
 p:=p||pg_catalog.jsonb_build_object('signature',hotels_published_architecture_private.sign_plan(p));
 RETURN pg_catalog.jsonb_build_object('contract_version','hotels_v2_published_conversion_readiness_v2','hotel_id',p_hotel_id,'status','READY','conversion_allowed',true,'blocking_reasons','[]'::jsonb,'plan',p);
END $plan$;

CREATE FUNCTION public.hotel_v2_admin_convert_legacy_hotel_to_v2_114489(p_plan jsonb,p_request_id uuid,p_confirmation text) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS '
DECLARE actor uuid; snapshot jsonb; before_hotel jsonb; after_hotel jsonb; business jsonb;
 r hotels_published_architecture_private.conversion_receipt%rowtype; result jsonb; relation record;
BEGIN
 PERFORM hotels_published_architecture_private.acquire_v2_locks(); actor:=auth.uid();
 PERFORM r5k_catalog_proof.executor_db9a78732b40d447eaa2();
 PERFORM hotels_published_architecture_private.assert_exact();
 IF actor IS NULL OR p_request_id IS NULL OR p_confirmation IS DISTINCT FROM ''CONVERT 7 KAMARES TO ROOMS_V2''
 OR jsonb_typeof(p_plan) IS DISTINCT FROM ''object''
 OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_plan) k) IS DISTINCT FROM
 ARRAY[''actor_id'',''assignment_id'',''authorization'',''authorization_hash'',''business_state_hash'',''catalog_epoch'',''commission_payment_hash'',''contract_version'',''expires_at'',''from'',''hotel_id'',''is_published'',''issued_at'',''lifecycle_hash'',''lineage_hash'',''partner_id'',''pricing_allocation_hash'',''public_booking_enabled'',''request_id'',''signature'',''snapshot_hash'',''snapshot_version'',''static_catalog_hash'',''to'']::text[]
 OR p_plan->>''contract_version'' IS DISTINCT FROM ''hotels_v2_published_conversion_plan_v2''
 OR p_plan->>''hotel_id'' IS DISTINCT FROM ''9b6d99a0-923a-4fbc-be54-c066e856e6ca''
 OR p_plan->>''actor_id'' IS DISTINCT FROM actor::text
 OR p_plan->>''request_id'' IS DISTINCT FROM p_request_id::text
 OR p_plan->>''partner_id'' IS DISTINCT FROM ''0a321bfe-da6b-43f6-8e0b-7c68546a8b18'' OR p_plan->>''assignment_id'' IS DISTINCT FROM ''a082c085-a6ea-46fd-8548-c8d9c6ee2c34''
 OR p_plan->''catalog_epoch'' IS DISTINCT FROM ''2''::jsonb
 OR p_plan->>''snapshot_version'' IS DISTINCT FROM ''hotels_v2_published_conversion_snapshot_v2''
 OR p_plan->>''from'' IS DISTINCT FROM ''legacy'' OR p_plan->>''to'' IS DISTINCT FROM ''rooms_v2''
 OR p_plan->''is_published'' IS DISTINCT FROM ''true''::jsonb OR p_plan->''public_booking_enabled'' IS DISTINCT FROM ''false''::jsonb
 OR p_plan->>''signature'' IS NULL
 OR p_plan->>''signature'' !~ ''^[0-9a-f]{64}$''
 OR hotels_published_architecture_private.sign_plan(p_plan) IS NULL
 OR p_plan->>''signature'' IS DISTINCT FROM hotels_published_architecture_private.sign_plan(p_plan)
 THEN RAISE EXCEPTION USING errcode=''22023'',message=''hotels_114489_invalid_plan''; END IF;
 SELECT * INTO r FROM hotels_published_architecture_private.conversion_receipt;
 IF FOUND THEN
  PERFORM hotels_published_architecture_private.assert_receipt_exact();
  IF r.id=p_request_id AND r.actor_id=actor AND r.expected_state_hash=p_plan->>''snapshot_hash''
   AND r.reviewed_plan_signature=p_plan->>''signature'' THEN
   RETURN jsonb_build_object(''contract_version'',''hotels_v2_published_conversion_result_v2'',''hotel_id'',r.hotel_id,
    ''request_id'',r.id,''architecture_version'',''rooms_v2'',''is_published'',true,''public_booking_enabled'',false,''replayed'',true);
  END IF;
  RAISE EXCEPTION USING errcode=''PT409'',message=''hotels_114489_already_converted'';
 END IF;
 IF (p_plan->>''expires_at'')::timestamptz<=clock_timestamp()
 OR (p_plan->>''issued_at'')::timestamptz>clock_timestamp()+interval ''5 seconds'' THEN
  RAISE EXCEPTION USING errcode=''PT409'',message=''hotels_114489_plan_expired''; END IF;
 snapshot:=hotels_published_architecture_private.snapshot_v2();
 IF hotels_published_architecture_private.digest(snapshot) IS DISTINCT FROM p_plan->>''snapshot_hash'' THEN
  RAISE EXCEPTION USING errcode=''PT409'',message=''hotels_114489_stale_snapshot''; END IF;
 before_hotel:=snapshot->''hotel''; business:=snapshot->''business'';
 INSERT INTO hotels_published_architecture_private.context(transaction_id,backend_pid,request_id,actor_id,before_hotel)
 VALUES(txid_current(),pg_backend_pid(),p_request_id,actor,before_hotel);
 UPDATE public.hotels SET architecture_version=''rooms_v2'',updated_at=clock_timestamp()
 WHERE id=''9b6d99a0-923a-4fbc-be54-c066e856e6ca'' AND architecture_version=''legacy'' AND is_published=true
 RETURNING to_jsonb(hotels.*) INTO STRICT after_hotel;
 IF before_hotel-ARRAY[''architecture_version'',''updated_at''] IS DISTINCT FROM after_hotel-ARRAY[''architecture_version'',''updated_at'']
 OR business IS DISTINCT FROM hotels_published_architecture_private.business_snapshot() THEN
  RAISE EXCEPTION USING errcode=''55000'',message=''hotels_114489_protected_business_changed''; END IF;
 r.id:=p_request_id;r.hotel_id:=''9b6d99a0-923a-4fbc-be54-c066e856e6ca'';r.partner_id:=''0a321bfe-da6b-43f6-8e0b-7c68546a8b18'';
 r.assignment_id:=''a082c085-a6ea-46fd-8548-c8d9c6ee2c34'';r.actor_id:=actor;r.converted_at:=clock_timestamp();
 r.reason:=p_confirmation;r.expected_state_hash:=p_plan->>''snapshot_hash'';r.before_hotel:=before_hotel;r.after_hotel:=after_hotel;
 r.reviewed_plan_signature:=p_plan->>''signature'';
 r.unchanged_business_hash:=hotels_published_architecture_private.digest(business);
 r.receipt_hash:=hotels_published_architecture_private.digest(to_jsonb(r)-''receipt_hash'');
 INSERT INTO hotels_published_architecture_private.conversion_receipt SELECT r.*;
 DELETE FROM hotels_published_architecture_private.context WHERE transaction_id=txid_current() AND backend_pid=pg_backend_pid() AND request_id=p_request_id;
 IF NOT FOUND THEN RAISE EXCEPTION ''hotels_114489_context_missing''; END IF;
 PERFORM hotels_published_architecture_private.snapshot_v2();
 result:=jsonb_build_object(''contract_version'',''hotels_v2_published_conversion_result_v2'',''hotel_id'',r.hotel_id,
 ''request_id'',r.id,''architecture_version'',''rooms_v2'',''is_published'',true,''public_booking_enabled'',false,''replayed'',false);
 RETURN result;
END ';

